quests[27303] = { id = 27303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mercy for the Bound", description = "It goes without saying that I had no desire to stay here, but there were materials we needed for the ritual... I delayed to secure them, and that is what lead to my capture.\n\nI will return to the circle, but I would be indebted to you if you would finish what I could not. We need hearts from the bound fire elementals that the Twilight's Hammer enslave in the western portion of the encampment.\n\nThe elementals are without hope, but in this sacrifice they can extract their revenge.\n\nFind me at camp.", sourceObjective = "Gather 5 Fleshburner Hearts.", progress = "Did you recover the hearts?", completion = "Thank you, {name}. You are quite capable. I'm extremely grateful that you've chosen to aid us.", sourceObjectiveStatus = "unverified-source-field" }
quests[27304] = { id = 27304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow the Sun", description = "Sunwalker Atohmo sends word from Orgrimmar -- he wishes to speak with you when you're in the city. I needn't remind you that Atohmo is an honored member of our order and his requests should not be ignored.\n\nNext time you are in Orgrimmar, travel to the Valley of Wisdom and speak with him.", sourceObjective = "Speak with Sunwalker Atohmo in Orgrimmar's Valley of Wisdom.", completion = "I've heard much of your contributions to the Horde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27305] = { id = 27305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Love and Family", description = "Inside the Scarlet Bastion is a painting of great personal value to Highlord Tirion Fordring. Search for a painting of our twin moons. Chip away at the paint until you uncover the master work, 'Of Love and Family.'\n\nMay the Light guide your actions, and please handle the painting with the utmost care.", sourceObjective = "Find 'Of Love and Family.'", progress = "The painting, {name}. Do you have the painting?", completion = "Master Fordring will be glad beyond measure to see this painting again.", sourceObjectiveStatus = "unverified-source-field" }
quests[27306] = { id = 27306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talk to Ogron", description = "I know this human, Paval Reethe. Pathetic, even for his kind. He deserted his fellow soldiers and is now hiding out in the woods.\n\nI sent Ogron out to track him down. Some of the others suspect he's been stealing from our supplies. I think I saw Ogron heading off to the southeast.", sourceObjective = "Find Ogron to the southeast of Brackenwall Village.", completion = "Ogron? Yeah, that me.\n\nShh. Keep voice down. Crocs hear you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27310] = { id = 27310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Weapons For You!", description = "Alright, these cowards want to fight? Let's see how well they do without any weapons.\n\nI'm sure you must have a torch, or something. Burn their weapon racks.\n\nBurn them all!", sourceObjective = "Burn 8 Grimtotem Weapon Racks.", progress = "We'll need to destroy more of their weapon racks if we're going to put a dent in their ability to fight.", completion = "Let's see them wage their war now!", sourceObjectiveStatus = "unverified-source-field" }
quests[27311] = { id = 27311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Weapons For You!", description = "The Grimtotem want to fight? Let us see how well they do without their weapons.\n\nI'm sure you must have something that burns. Set their weapon racks ablaze, my {class} friend.\n\nLet nature take its course.", sourceObjective = "Burn 8 Grimtotem Weapon Racks.", completion = "Let us see how well they fight without their weapons.", sourceObjectiveStatus = "unverified-source-field" }
quests[27312] = { id = 27312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkcloud Grimtotem", description = "There's no way around it. If you want to win a battle, you have to spill some blood. In this case... a lot of it.\n\nYou know what we have to do.", sourceObjective = "Slay 20 Grimtotem Tauren at Darkcloud Pinnacle.", completion = "That put a dent in their numbers! Can't say that they didn't deserve it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27313] = { id = 27313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkcloud Grimtotem", description = "There is no alternative: if you intend to win a battle, you must spill the enemy's blood. In this case, unfortunately, a lot of it.\n\nYou know what we have to do.", sourceObjective = "Slay 20 Grimtotem Tauren at Darkcloud Pinnacle.", completion = "While the Earth Mother does not condone such violence, we had no choice. The Grimtotem have ignored Her teachings for too long and are reaping what they have sown.", sourceObjectiveStatus = "unverified-source-field" }
quests[27314] = { id = 27314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Isha Gloomaxe", description = "Sentinel training 101: take out their leaders and your enemy's forces will soon fall apart. We're going to do just that, {class}.\n\nIsha Gloomaxe is the closest of the Grimtotem chiefs. Let's see if we can't take her measure.", sourceObjective = "Slay Isha Gloomaxe.", completion = "She was tougher than I thought. We worked well together, but we're going to have to make sure not to underestimate the other Grimtotem chiefs.", sourceObjectiveStatus = "unverified-source-field" }
quests[27315] = { id = 27315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Isha Gloomaxe", description = "Basic brave philosophy dictates that if you kill the leaders and your enemy's forces, they will soon fall into disarray. We are going to do just that, {class}.\n\nIsha Gloomaxe is the closest of the Grimtotem chiefs. We will test her and her axe, and she will be found wanting.", sourceObjective = "Slay Isha Grimtotem.", completion = "She was more formidable than her reputation suggested. Although we worked well together, we must make certain not to underestimate the other Grimtotem chiefs.", sourceObjectiveStatus = "unverified-source-field" }
quests[27316] = { id = 27316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rattle of Bones", description = "A tauren rattle lays here, exuding supernatural power. Its keepers slain, the artifact is undefended.\n\nPerhaps the sentinel will have some insight into its significance?", sourceObjective = "Give the Rattle of Bones to the Feralas Sentinel at Darkcloud Pinnacle in Thousand Needles.", progress = "That's the fabled Rattle of Bones, {name}!", completion = "It's true then! What is it doing here, though? And if it's here, that must mean that the writ and the drums are also nearby!\n\nMaybe there's some link between it and the wind serpent that just appeared? I think that I've an idea what that creature is as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27317] = { id = 27317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rattle of Bones", description = "A tauren rattle lays here, exuding supernatural power. Its keepers slain, the artifact is undefended.\n\nSurely the brave will have some insight into its significance?", sourceObjective = "Give the Rattle of Bones to the Freewind Brave at Darkcloud Pinnacle in Thousand Needles.", progress = "The fabled Rattle of Bones, {name}!", completion = "It is true then! What is it doing here, though? And if it is here, that must mean that the writ and the drums are also nearby!\n\nPerhaps there is some link between it and the wind serpent that just appeared? I think that I have an idea what that creature is as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27318] = { id = 27318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Elder Stormhoof", description = "Elder Stormhoof is a shaman of immense power. Supposedly, he is a direct disciple of Magatha Grimtotem, the Elder Crone, leader of the Grimtotem clan.\n\nWe know that he's here and that he's been training their geomancers. We have to kill him, {class}.", sourceObjective = "Slay Elder Stormhoof.", completion = "That's two of them. Two more to go.\n\nI wonder what he meant about being \"chosen\"?", sourceObjectiveStatus = "unverified-source-field" }
quests[27319] = { id = 27319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Elder Stormhoof", description = "Elder Stormhoof is a shaman chief of immense power. He was taught by Magatha Grimtotem, the Elder Crone, leader of the Grimtotem clan.\n\nWe know that he is here and that he has been training their geomancers. We have to kill him, {class}.", sourceObjective = "Slay Elder Stormhoof.", completion = "That was not pleasant. I wonder what he meant by calling you, \"the Chosen\"?", sourceObjectiveStatus = "unverified-source-field" }
quests[27320] = { id = 27320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Writ of History", description = "In shu'halo myth, the Rattle of Bones is connected with the Writ of History and the Drums of War. They are supposed to be powerful tauren artifacts.\n\nWe must keep our eyes peeled if we're to find the other two. The writ will most likely look like some kind of pictographic scroll if the stories are to be believed.", sourceObjective = "Collect the Writ of History.", progress = "We'll need the actual writ, not just any tauren scroll hanging.", completion = "I'm fairly certain that's it. This is very intriguing, {name}. What are they doing here? Are they being used as a weapon?\n\nThe wind serpent flew northwest to that next bluff. Maybe that's where the drums are?", sourceObjectiveStatus = "unverified-source-field" }
quests[27321] = { id = 27321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Writ of History", description = "The Rattle of Bones is a part of shu'halo ancient myth. It is always connected with the Writ of History and the Drums of War. They are supposed to be powerful tauren artifacts; gifts from the Earth Mother if the tales are to be believed. I cannot imagine Her being connected with the drums, though.\n\nWe must be vigilant if we are to find the other two. The writ will look like a pictographic scroll if memory serves.", sourceObjective = "Collect the Writ of History.", progress = "We will need the actual writ, and not just any scroll hanging.", completion = "This is very exciting and also worrisome, {name}. What are these artifacts doing here? Are they being used as a weapons against us by the Grimtotem?\n\nThe wind serpent flew northwest to that next bluff. Maybe that's where the drums are?", sourceObjectiveStatus = "unverified-source-field" }
quests[27322] = { id = 27322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korok the Colossus", description = "The monstrosity has fallen, granting a brief reprieve to the Forsaken soldiers on the front lines.\n\nTake Korok's second head and return it to Forward Commander Onslaught at Forsaken Forward Command.", sourceObjective = "Take Korok's Second Head to Forward Commander Onslaught at Forsaken Forward Command in the Ruins of Gilneas.", progress = "Korok is dead?", completion = "That towering behemoth has killed hundreds of Forsaken soldiers. You've done a great thing, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27323] = { id = 27323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Grundig Darkcloud", description = "One of the infamous Grimtotem leaders of the Stonetalon Mountains has returned home.\n\nWe should take this opportunity to make sure that he doesn't go anywhere else.", sourceObjective = "Slay Grundig Darkcloud.", completion = "<The sentinel gives you an appraising look.>\n\nWhat is it with you? Why do they all seem spooked by you being here?", sourceObjectiveStatus = "unverified-source-field" }
quests[27324] = { id = 27324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Grundig Darkcloud", description = "One of the most accomplished Grimtotem leaders of the Stonetalon Mountains has returned home.\n\nWe must make the most of this chance and put an end to his campaign of terror once and for all.", sourceObjective = "Slay Grundig Darkcloud.", completion = "<The brave gives you an appraising look.>\n\nThere is something special about you, {name}. That much is certain.", sourceObjectiveStatus = "unverified-source-field" }
quests[27325] = { id = 27325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drums of War", description = "Whatever the Grimtotem are doing with these Drums of War, we don't want them to have them.\n\nDon't worry, {name}, we'll figure it all out. But first, we need to gather all of the pieces of the puzzle.", sourceObjective = "Collect the Drums of War.", progress = "The tauren love their drums. I can only imagine the Drums of War will be somehow different from the others.", completion = "Surely that was the voice of the Elder Crone!\n\nWe must be very careful, {name}. Great danger lies ahead if Magatha Grimtotem has taken notice of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27326] = { id = 27326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drums of War", description = "Whatever it is that the Grimtotem are doing with the Drums of War, we do not want them to keep them.\n\nDo not worry, {name}, we will figure out what is going on here. But first, we need to gather all of the artifacts.", sourceObjective = "Collect the Drums of War.", progress = "War is not an activity to engage in for those who are faithful to the Earth Mother's teachings.", completion = "Surely that was the voice of the Elder Crone!\n\nWe must be very careful, {name}. Great danger lies ahead if Magatha Grimtotem has taken notice of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27327] = { id = 27327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: The Chief of Chiefs", description = "And now the time has come to take out the leader of all of the Darkcloud Pinnacle Grimtotem: Arnak Grimtotem.\n\nIt is said that he's the disgraced nephew of Magatha Grimtotem, the Elder Crone and matriarch of the Grimtotem clan. Supposedly, his indiscretions have left him in a state of disfavor with her.\n\nBut none of that matters right now. All that matters is that we kill him. For good this time.", sourceObjective = "Slay Arnak Grimtotem.", completion = "For some reason they all think that you've been sent by Magatha Grimtotem. I know it must have something to do with that wind serpent that's been hanging around.\n\nDoesn't matter. Their leader is dead. It's only a matter of time before the tauren of Freewind Post regain their home.\n\nIf I were them, I'd push back a little to teach the Grimtotem a lesson, but they probably won't. They're tauren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27328] = { id = 27328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: The Chief of Chiefs", description = "The time has come to deal with the leader of the Darkcloud Pinnacle Grimtotem: Arnak Grimtotem.\n\nHe is the disgraced nephew of Magatha Grimtotem, the Elder Crone and matriarch of the Grimtotem clan. His indiscretions have left him in a state of disfavor with her.\n\nNone of that matters now. All that matters is that we deal with him. Once and for all.", sourceObjective = "Slay Arnak Grimtotem.", progress = "Arnak must fall, {name}, if we are to win the battle against the Grimtotem.", completion = "They all believed that you have been sent by Magatha Grimtotem. There is no arguing that her pet, Arikara, has been lurking about.\n\n<The brave gives you a long look.>\n\nIt does not matter. Arnak is dead. It is only a matter of time before we take back Freewind Post.\n\nPerhaps now we will be able to establish a lasting peace with the Grimtotem?", sourceObjectiveStatus = "unverified-source-field" }
quests[27329] = { id = 27329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invoking the Serpent", description = "I am familiar with these artifacts. I believe that they were brought here by Magatha Grimtotem herself. But she's not amongst the Grimtotem on Darkcloud Pinnacle. She disappeared right after she arrived, and no one knows where she is now.\n\nMaybe we can find out.\n\nTake the rattle, the writ, and the drum out to Arikara's Needle. If my guess is correct, the wind serpent will appear again. You'll have to defeat it to gain knowledge of where Magatha is hiding.", sourceObjective = "Defeat Arikara.", progress = "Only by subduing Arikara will you discover where Magatha Grimtotem is hiding.", completion = "So, she's been taken prisoner by the Twilight's Hammer. I can't say that I feel sorry for her, but she might prove even more dangerous in their hands.", sourceObjectiveStatus = "unverified-source-field" }
quests[27330] = { id = 27330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invoking the Serpent", description = "I am familiar with these artifacts. I believe that they were brought here by Magatha Grimtotem herself. But she's not amongst the Grimtotem on Darkcloud Pinnacle. She disappeared right after she arrived, and no one knows where she is now.\n\nMaybe we can find out.\n\nTake the rattle, the writ, and the drum out to Arikara's Needle. If my guess is correct, the wind serpent will appear again. You'll have to defeat it to gain knowledge of where Magatha is hiding.", sourceObjective = "Defeat Arikara.", progress = "Only by subduing Arikara will you discover where Magatha Grimtotem is hiding.", completion = "So, she's been taken prisoner by the Twilight's Hammer. I can't say that I feel sorry for her, but she might prove even more dangerous in their hands.", sourceObjectiveStatus = "unverified-source-field" }
quests[27331] = { id = 27331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seer's Call", description = "I just received word that you are needed in Orgrimmar, {name}. Seer Liwatha has asked for you to return to the city as quickly as you are able. Her message didn't include any other information, and the matter seemed urgent.\n\nLook for Seer Liwatha in Orgrimmar's Valley of Wisdom.", sourceObjective = "Speak with Seer Liwatha in Orgrimmar's Valley of Wisdom.", sourceObjectiveStatus = "unverified-source-field" }
quests[27332] = { id = 27332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Shadow-Walker", description = "Shadow-Walker Zuru requires your presence in Orgrimmar right away, {name}. Do not keep him waiting, as it sounds like a matter of some importance.\n\nYou can find the shadow-walker in the Valley of Spirits inside Orgrimmar.", sourceObjective = "Speak with Shadow-Walker Zuru in Orgrimmar's Valley of Spirits.", sourceObjectiveStatus = "unverified-source-field" }
quests[27333] = { id = 27333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losing Ground", description = "I don't know how much longer we can hold out for, {name}. Crowley and Bloodfang's worgen know every hidey hole and safe spot in Gilneas. One minute they're standing in front of you and the next minute they're gone! We're gonna lose this war to attacks of opportunity, even though we have a superior military presence.\n\nBut momma didn't raise no quitter! Forsaken until the end, my friend.\n\nHead west into the headlands and help our soldiers on the front line. Kill the attacking worgen rebels!", sourceObjective = "Kill 12 Worgen Rebels.", completion = "If I could still breathe I'd let out a sigh of relief.\n\nDon't get too comfortable, though, {name}, your mission here has just begun.", sourceObjectiveStatus = "unverified-source-field" }
quests[27334] = { id = 27334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Cleric Cecille", description = "I just received a message from Dark Cleric Cecille in Orgrimmar. She requests that you join her in the audience chamber in Grommash Hold, where you can find her with the delegation from Undercity. The cleric didn't mention the purpose of your visit, but it is clearly important. Make haste, {name}.", sourceObjective = "Speak with Dark Cleric Cecille in Grommash Hold inside Orgrimmar's Valley of Strength.", completion = "There you are, {name}. I was beginning to think my message hadn't found you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27335] = { id = 27335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from Tyelis, a priest trainer and emissary from Silvermoon.\n\nHe asks you to meet him inside Grommash Hold in Orgrimmar. You should make your way there immediately, {name}. It sounds important.", sourceObjective = "Speak with Tyelis at Grommash Hold in Orgrimmar's Valley of Strength.", completion = "Welcome, {name}. I'm glad that you accepted my invitation. We have much to discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[27336] = { id = 27336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem Weapon", description = "During the last Grimtotem attack, I was wounded, but not before I managed to capture a curious totem our enemies were using against us.\n\nIt seemed to be emitting raw bolts of energy during the battle, but in all my experiments, I haven't managed to figure out how it works. I'll loan the totem to you if you agree to help me test it.\n\nThe watery areas surrounding the farm are home to pesky mottled drywallow crocolisks and drywallow daggermaws. Try fighting the crocolisks near the totem.", sourceObjective = "Use the Captured Totem to set it on the ground, and kill 10 Mottled Drywallow Crocolisks or Drywallow Daggermaws near it to test its effects.", progress = "Have you had any luck testing the totem?", completion = "<The apprentice listens as you describe your experiment.>\n\nA haze and some lightning? That's it? There's got to be more to the totem than just that! The Grimtotems aren't likely to bring something like this to the battlefield unless it has some kind of utility.", sourceObjectiveStatus = "unverified-source-field" }
quests[27337] = { id = 27337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fitting Weapon", description = "From your earliest days, {name}, your trainers identified you as a natural talent. Your rapid progress and dedication have made you an example.\n\nIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nLegend has it that the cursed Shadowfang Keep in Silverpine Forest is home to a variety of materials that you will need. Travel there and find the lost Silverlaine family sword, a supply of moonsteel ingots, and sinew from ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Silverlaine Family Sword from Baron Silverlaine, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ander told me to expect you. It's quite an honor to be crafting a weapon for you, {name}. With these materials, it will be a fine blade indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27338] = { id = 27338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Boys on the Shore", description = "The situation here in the Highlands changes by the minute. Our objective is to storm the Bastion of Twilight, but I can't even secure a landing zone on the shore without the blasted Horde creating trouble.\n\nWhile I scrape together the remains of the fleet, I need men on the shore securing the beach head.\n\nReport to Lieutenant Emry on the shore and help his marines to beat back the Horde!", sourceObjective = "Report to Lieutenant Emry at the Twilight Shores in the Twilight Highlands.", completion = "Keep your head down 'fore you lose it, {class}!\n\nThis is MY beach.\n\nThe Horde WANTS my beach.\n\nThey will NOT have my beach.\n\nIs the beach situation clear?", sourceObjectiveStatus = "unverified-source-field" }
quests[27339] = { id = 27339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reagent Thief", description = "If there's one thing you can count on Apprentice Morlann to do, it's whine about reagents.\n\nNormally, I just ignore him, and it never works. This time, I'm going to try something different.\n\nMaybe if I replace the missing reagents before he notices, he'll leave me alone. The most common reagent we both use is marsh venom, which comes from the darkfang creepers and noxious shredders in the marsh north of the farm. If you bring me the venom, I'll replace it before Morlann notices it's gone.", sourceObjective = "Collect 6 vials of Marsh Venom from Darkfang Creepers or Noxious Shredders.", progress = "Did you get that venom? Morlann's going to discover that it's gone any moment now...", completion = "<Apprentice Garion inspects the venom.>\n\nThis is absolutely perfect! He'll never know the difference.", sourceObjectiveStatus = "unverified-source-field" }
quests[27340] = { id = 27340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direhorn Raiders", description = "The Grimtotems up at Direhorn Post, just to the north, are getting bolder by the day. At night, you can often hear them chanting about their deeds in battle against people who've tried to settle here.\n\nThey're determined to drive us from Tabetha's farm even though she's trained generations of apprentices here. We've defended the farm as best we can, but Apprentice Garion was wounded in the last attack.\n\nGo to Direhorn Post and kill any Grimtotem you can find! The attacks must stop.", sourceObjective = "Kill 12 Grimtotem in Direhorn Post.", completion = "<Apprentice Morlann nods.>\n\nGood. Can't say I'll miss the company, if you can call it that. You'd think at least in the middle of the swamp you'd get some privacy, you know?", sourceObjectiveStatus = "unverified-source-field" }
quests[27341] = { id = 27341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Shore", description = "It's them or us, {class}. Only one of us can command this beach.\n\nNorth of here you'll see a small hill with a commanding view of the shoreline. Whoever controls that hill will have the upper hand up and down the shore!\n\nI need to know what the current situation is. Scout the beach head control point, marked by that enormous flag, and return to me.\n\nYou don't have to try to capture it, unless you're spoiling for a fight...", sourceObjective = "Scout the Beach Head Control Point on the Twilight Shore. You don't need to capture it, but doing so will give your side a combat advantage and flag you for PvP.", progress = "What's the word out there, {name}?", completion = "That's the lay of the land, soldier. If you're having trouble fighting here on the coast, you might consider pitching in and helping us take and hold that hill.", sourceObjectiveStatus = "unverified-source-field" }
quests[27342] = { id = 27342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Time, All Will Be Revealed", description = "The Dark Lady has sent you and Arthura here for a very specific purpose. Before I tell you more, we must make preparations.\n\nHead east into the forest of Gilneas and search near the trees and rocks of the region for a special plant known as wolfsbane. Gather as much of the wolfsbane as you can carry and return to me.\n\nOur mission here goes far beyond the scope of the battlefield, {name}. In time, all will be revealed.", sourceObjective = "Collect 6 Wolfsbane.", progress = "Did you gather the wolfsbane?", completion = "<Belmont takes the wolfsbane from you.>\n\nGood. Now just do as Forward Commander Onslaught commands. Try your best to fit in with the rest of the soldiers. We don't want the Gilneas Liberation Front to get suspicious.\n\nOh, you didn't know they were watching us? Right now there are five different worgen spies looking down on our position. Just be calm and follow orders. I'll let you know when we are ready to proceed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27343] = { id = 27343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hand of the Light", description = "I have been watching your progress, {name}, and I can only conclude that the Light shines brightly upon you. You are becoming an exemplary {class}.\n\nTo honor your dedication, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nThe materials to make your weapon are unique, and only found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Do you have the materials for your weapon?", completion = "Lord Grayson has told me much about you and your dedication to the Light and the Alliance. It will be a great honor to craft a hammer for you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27344] = { id = 27344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Well-Earned Reward", description = "I am not the only one impressed by your progress {name}. Your mastery of bow and pet and your dedication to the Alliance have reached the ears of King Wrynn.\n\nIn recognition of your service, the king has commissioned the royal bowyer to craft a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is home to the unique materials needed for your weapon. Travel there and obtain the scope from Lord Godfrey's gun, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Godfrey's Crystal Scope from Lord Godfrey, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Who knew that cursed old keep hid such valuable items? I'll be honored to craft them into a fine weapon for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27345] = { id = 27345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The F.C.D.", description = "Communications are down with all of our frontline outposts, {name}. As of right now I don't have a damn clue as to the status of our troops in Gilneas. We need to re-establish communications.\n\nI need you to head west into the headlands and find our outpost on the coast. By now the soldiers there are likely all dead, but their F.C.D. might be operational. Grab the device and get back to me.", sourceObjective = "Recover the Forsaken Communication Device.", progress = "Recover the F.C.D.", completion = "With this device I will be able to communicate with you in the field. Now to check the rest of our frontline outposts.", sourceObjectiveStatus = "unverified-source-field" }
quests[27346] = { id = 27346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zeppelin Crash", description = "Not long ago, a goblin zeppelin crashed to the east. A representative of the Steamwheedle Cartel passed through here a few days ago.\n\nShe was looking for information about the zeppelin's cargo and its pilot, Beezil, but none of us really got a good look at the crash. I doubt she'll be able to clean up after the wreck by herself, much less recover whatever cargo the vessel might have carried.\n\nIf you have time, you may want to check up on her out at Beezil's Wreck, due east of here, near the mountains.", sourceObjective = "Speak with Moxie Steelgrille at Beezil's Wreck.", completion = "So those hermit mages sent you? How can I be sure that I can trust you?\n\nI suppose I can use the help. There's not much here a mage would be interested in, anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[27347] = { id = 27347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrosion Prevention", description = "Just look at this area! It's swarming with oozes. If I don't find some way to keep them under control, they'll corrode the wreckage and the zeppelin's cargo!\n\nI can't go back empty-handed, {class}! Help me dissolve these oozes before they've digested everything!\n\nThis device, when powered, will concentrate energy on the slimes, causing them to explode. The zeppelin's fragmented power core should power the device. The one near the main crash works all the time, but the others flicker on and off.", sourceObjective = "Moxie Steelgrille wants you to dissolve 10 oozes and report back to her at Beezil's Wreck.", progress = "Did you make any progress against those oozes?", completion = "Well, it does look a little cleaner out there...\n\nI suppose it's time to get down to the business of salvaging this wreckage.", sourceObjectiveStatus = "unverified-source-field" }
quests[27348] = { id = 27348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secure the Cargo!", description = "This zeppelin was carrying six months' worth of supplies to us at Mudsprocket! Sure, they've been able to barter for some of what they need, but they won't hold out forever.\n\nI've been sent out here to recover what I can of the cargo, but the wreckage is scattered all over the marsh in this area. I'm sure a lot of the cargo didn't survive the crash, but are you willing to help me recover what we can?", sourceObjective = "Moxie Steelgrille at Beezil's Wreck wants you to recover 8 pieces of Zeppelin Cargo.", progress = "<Moxie looks frantic with worry.>\n\nDid the cargo survive? Did you find any of it?", completion = "Wow! You certainly found a lot more than I expected would be out there. I'm not sure how much Drazzit thought we were going to find out here, but he's going to have to be happy with this for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[27349] = { id = 27349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break in Communications: Dreadwatch Outpost", description = "I'm not gonna lie to you, {name}. What I'm about to ask you to do is suicide. Chance of failure is about 95%.\n\nAll communication from Dreadwatch Outpost has been severed. With the worgen constantly rushing us we have no means by which to get to Dreadwatch to check on our soldiers. I need you to head south to the outpost and check on our soldiers. I'll keep in contact through the Forsaken communication device - F.C.D. - from here on out.\n\nKEEP CLEAR OF THE MAIN ROAD.", sourceObjective = "Investigate Dreadwatch Outpost.", progress = "Status?", completion = "<The F.C.D. crackles with static.>\n\nDreadwatch is lost? This is bad, {name}. Real bad.\n\nIf Dreadwatch is compromised it means we've lost Gilneas City.", sourceObjectiveStatus = "unverified-source-field" }
quests[27350] = { id = 27350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break in Communications: Rutsak's Guard", description = "<The F.C.D. hums.>\n\nOur next outpost is Rutsak's Guard, located due east of Dreadwatch. Make your way to Rutsak's while avoiding the worgen rushers, {name}. You don't want to deal with those monsters by yourself.\n\nIf you make it there in one piece, look for Captain Rutsak.\n\nJust be prepared for the worst.", sourceObjective = "Find Captain Rutsak at Rutsak's Guard in the Ruins of Gilneas.", completion = "Th... Af... After we lost Gilneas City, the port fell.\n\nHU... HUM... HUMANS ARE HERE! Reinforcements from Stormwind! They slaughtered my men. Left me alive to witness their strength. To tell high command... To tell them that the 7th Legion are here...", sourceObjectiveStatus = "unverified-source-field" }
quests[27351] = { id = 27351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Reward", description = "SI:7 has been watching your progress with interest. You service to the Alliance is well-known and tales of your deeds have reached the king's ears.\n\nIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is home to the exotic materials for your weapon. Travel there and recover Commander Springvale's sharpening stone, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Springvale's Sharpening Stone from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "It was quite an honor to receive the commission for your weapon, {name}. When Tony mentioned using so many exotic materials, I had my doubts, but it seems you managed to find them all. This will be a fine reward for all you've done for the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27352] = { id = 27352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liquid Gold", description = "As the Scourge swept through Stratholme like a plague, the Knights of the Silver Hand manufactured holy water to use against the invaders. They stored it inside small crates along with other vital supplies, and distributed them throughout the city. Unfortunately, the citizens turned into Scourge reinforcements before the supplies could ever be used!\n\nThese supply crates will prove extremely useful to our efforts. Bring me a vial of Stratholme Holy Water, we need to have it replicated in mass quantities.", sourceObjective = "Find a vial of Stratholme Holy Water.", progress = "Is that the vial of Stratholme Holy Water?\n\nWait, is that just regular water? Don't play games with ol' Stonebruiser!", completion = "Excellent! I think the holy water will prove devastating in large volumes.", sourceObjectiveStatus = "unverified-source-field" }
quests[27353] = { id = 27353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of the Elements", description = "Your talent has attracted much attention in shamanic circles, {name}. Word of your mastery of the elements and dedication to the Alliance has even reached the palace.\n\nIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nThe materials for your weapon can only be found in Silverpine Forest's cursed Shadowfang Keep. Travel there and retrieve Lord Walden's talisman, the Book of Lost Souls, and the essence of the ghosts haunting the castle.", sourceObjective = "Go to Shadowfang Keep and obtain Walden's Talisman, the Book of Lost Souls, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I have rarely had the chance to work with such exotic materials, but even I can sense the power residing within them. I will have the honor of crafting an incredible weapon for you, {name}. The farseer did not underestimate your abilities when she told me about you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27354] = { id = 27354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Arcane", description = "You have proven yourself a brilliant student and a dedicated servant of the Alliance. Word of your accomplishments has even reached the ears of the king.\n\nIn recognition of your service, King Wrynn has commissioned the royal enchanter to create a special weapon.\n\nThe materials required for your staff are found only in Silverpine Forest's cursed Shadowfang Keep. Travel there and find a lost heirloom of the Silverlaine family, a supply of moontouched wood, and the essence of the ghosts haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Silverlaine's Enchanted Crystal from Baron Silverlaine, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ah, I have been expecting you, {name}. Maginor Dumas has spoken highly of you and the royal commission only confirms his words. It is an honor to be able to craft a staff for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27355] = { id = 27355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Boon for the Powerful", description = "The king is finally beginning to take note of our power and our value to the Alliance, thanks to your deeds. Perhaps they are beginning to accept our kind.\n\nKing Wrynn has commissioned the royal enchanter to create a powerful weapon in recognition of your achievements.\n\nThe materials you will need come from Silverpine Forest's Shadowfang Keep. Travel there and obtain the tenebrous orb held by Lord Godfrey, the Book of Lost Souls, and the essence of the ghosts haunting the castle.", sourceObjective = "Go to Shadowfang Keep and obtain the Tenebrous Orb from Lord Godfrey, the Book of Lost Souls, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I won't ask what you had to do to come by such rare and powerful materials, but I'm glad to have the chance to work with them. Your weapon will be magnificent!", sourceObjectiveStatus = "unverified-source-field" }
quests[27356] = { id = 27356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Circle's Future", description = "The Cenarion Circle is pleased with your progress, {name}. You are a credit to all druids and we look to you and your peers as the future of of our brotherhood.\n\nThe circle has decided to honor you with the creation of unique staff.\n\nThe rare and powerful materials needed for your staff can only be found in Shadowfang Keep inside Silverpine Forest. Travel there and retrieve Lord Walden's collection of elixirs, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Walden's Elixirs from Lord Walden, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your staff?", completion = "Ah, you must be the {class} Loganaar was talking about. It is a pleasure to finally meet you. Loganaar and other members of the circle speak highly of you. It will be an honor to make a weapon for such a {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27357] = { id = 27357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captive Bride", description = "Of course! Lakota Windsong! Why didn't I think of this before?\n\nArnak kidnapped Lakota years ago and tried to force her into being his bride. She managed to escape, but in the chaos of the recent attack on Freewind Post, he took her again.\n\nShe has to be around here somewhere. She's become quite the mystic in recent years. I'm guessing she'll know what to do with these tauren artifacts.", sourceObjective = "Speak with Lakota Windsong at Darkcloud Pinnacle in Thousand Needles.", completion = "It is embarrassing to have been kidnapped by Arnak again. I heard the fighting outside. Did you kill him?\n\n<The shaman looks sad for just a moment.>\n\nI am happy to be free once more. Now, how can I help you, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27358] = { id = 27358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captive Bride", description = "Lakota Windsong! Why did I not think of this before?\n\nArnak kidnapped Lakota years ago and tried to force her to be his bride. With help, she was able to escape, but in the chaos of the recent attack on Freewind Post, he took her again.\n\nShe must be near. She has become quite the shaman in recent years. I am sure that she will understand the significance of the rattle, the writ, and the drums.", sourceObjective = "Speak with Lakota Windsong at Darkcloud Pinnacle in Thousand Needles.", completion = "It is embarrassing to have been kidnapped by Arnak again. I heard the fighting outside. Did you kill him?\n\n<The shaman looks sad for just a moment.>\n\nI am happy to be free once more. Now, how can I help you, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27359] = { id = 27359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Reinforcements", description = "The Scourge have some sort of ward in place that's preventing me from opening a portal so that our reinforcements can help us take the city! It's like a neverending screaming inside of my head! Agh!\n\nI'm doing all I can to retain my sanity from that noise with this barrier. My best guess is that the banshees are maintaining the defense. If you could bring me some of their essences, I think I can use them to counteract the ward and get our boys in here!", sourceObjective = "Obtain 4 Banshee Essences.", progress = "Were you able to obtain the essences? Be careful, they're deadly spellcasters.", completion = "Oh my... the banshees are very tortured souls indeed. Merely holding their essence is emotionally painful...\n\nEnough of that for now. I'll get to work on counteracting their magic, then we'll have a portal up and running in no time. Stratholme will be ours soon, I just know it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27360] = { id = 27360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for Our Soldiers", description = "7th Legion... They rushed us in the dead of the night. Their captain barked orders as the submariners slaughtered my men. Then he came to me, put his face in mine, and said something I'll never forget:\n\n\"The name's Master Sergeant Pietro Zaren, officer in the 7th Legion. When you see your soldiers being slaughtered in your nightmares - if you even still dream - remember my name and tremble.\"\n\nAvenge my soldiers! Kill the 7th Legion occupying the Cathedral Quarter of Gilneas City, southwest of here.", sourceObjective = "Kill 10 7th Legion Submariners.", completion = "Though we were shamed in battle, the enemy was not victorious. I will not soon forget this, {name}.\n\nIf I make it back to Silverpine I will likely retire from the service. War is not in my blood.", sourceObjectiveStatus = "unverified-source-field" }
quests[27361] = { id = 27361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favored of the Light", description = "The Light truly shines in you and your dedication to the Alliance, {name}. You serve as an example to your fellow priests and comrades in arms.\n\nIn recognition of your deeds, King Wrynn has commissioned the royal enchanter to create a special staff.\n\nThe materials for such a weapon can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I can't believe you managed to get all those materials. I wouldn't think of venturing into Shadowfang Keep! The stories about that place are horrific.\n\nEnough of that, though. This is a time to recognize your achievements, not prattle on about my silly fears.", sourceObjectiveStatus = "unverified-source-field" }
quests[27362] = { id = 27362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favored of Elune", description = "You are a true servant of Elune, an example to our people, and stalwart servant of the Alliance. The Temple of the Moon and the court of Stormwind wish to honor your achievements.\n\nWe have commissioned the royal enchanter to create a staff for you.\n\nThe materials for your staff can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I can't believe you managed to get all those materials. I wouldn't think of venturing into Shadowfang Keep! The stories about that place are horrific.\n\nEnough of that, though. This is a time to recognize your achievements, not prattle on about my silly fears.", sourceObjectiveStatus = "unverified-source-field" }
quests[27363] = { id = 27363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Budding Young Surgeon", description = "You have shown yourself to be a capable priest and a credit to the people of Gnomeregan. The high tinker and the king of Stormwind wish to honor your contribution to the Alliance.\n\nThey have commissioned the royal enchanter to create a special staff.\n\nThe materials for such a weapon can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I can't believe you managed to get all those materials. I wouldn't think of venturing into Shadowfang Keep! The stories about that place are horrific.\n\nEnough of that, though. This is a time to recognize your achievements, not prattle on about my silly fears.", sourceObjectiveStatus = "unverified-source-field" }
quests[27364] = { id = 27364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Whose Orders?", description = "<The F.C.D. buzzes.>\n\nThe 7th Legion are an elite special ops regiment. They've been there, behind the scenes, for almost every major offensive and military engagement the Alliance has ever done. This is bad news. How did they get past our warships? And on whose orders are they here?\n\nWe need to get our hands on their orders. This Pietro character will undoubtedly have vital information. Find him at the Cathedral Quarter in Gilneas City and take him out. Search his corpse for clues.", sourceObjective = "Recover the Orders from High Command.", progress = "Status?", completion = "<The F.C.D. crackles with electricity.>\n\nAn Alliance armada is en route? How could this have happened?\n\n<Forward Commander Onslaught cuts out for a moment. You hear worgen howling in the background.>\n\nYou've got to hurry, {name}. We're being overrun up here at Forward Command.", sourceObjectiveStatus = "unverified-source-field" }
quests[27365] = { id = 27365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fitting Weapon", description = "From your earliest days, your trainers always knew you would make your mark on the Horde. You have fought bravely and given our enemies reason to fear.\n\nAs a reward for your dedication, the warchief has commissioned his personal smith to forge a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost Silverlaine family sword, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Silverlaine Family Sword from Baron Silverlaine, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Grezz Ragefist told me to expect you. Those materials will make a fine sword. Always use it for the glory of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27366] = { id = 27366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landgrab", description = "The Horde's Axebite Marines are all up in my precious, precious beach.\n\n<The Lieutenant points north, along the shore.>\n\nKill them.", sourceObjective = "Slay 12 Axebite Marines on the Twilight Shores in Twilight Highlands.", progress = "You're still alive, {name}.\n\nAre they?", completion = "Dead? By the dozen?\n\nIt's a start, {class}. It's a start.", sourceObjectiveStatus = "unverified-source-field" }
quests[27367] = { id = 27367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin Goldbraids", description = "I love my boys, don't get me wrong.  But I TOLD them that I needed FIVE MINUTES to water and brush the horses, and what did they do?  They made a stupid bet with each other and ran off!  I should have known better... this always happens.\n\nGidwin's the short one.  He headed north, along the river.  If you're headed that direction, would you tell him to come back?  We've got to get to Light's Hope Chapel, and I'm not against leaving without him.", sourceObjective = "Find Gidwin Goldbraids in Eastern Plaguelands.", completion = "Tarenar?  Is that you?\n\nWhoever you are, would you mind helping me out of this thing?", sourceObjectiveStatus = "unverified-source-field" }
quests[27368] = { id = 27368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Encased", description = "You should have seen me fight!  I must have killed six of those beasts, when...\n\nOh wait, you can count the bodies, can't you?  OK, fine.  I killed four of them, when the fifth one shot me with this web.  To make things even worse... when he blasted me with web juice, my mouth was open!\n\nI can't seem to break these webs, and I doubt you'll be able to, either.  No, you'll have to get some of the stomach juice from those undead spider-things.  That'll do the trick.", sourceObjective = "Obtain 8 vials of Crypt Bile from nerubians in Terrorweb Tunnel.", progress = "Oh boy... Fiona is going to be madder than a wet harpy.  You'd better hurry.", completion = "You're back?!  Thank the Light!\n\nBefore you throw that acid on me, I need to ask: Are you the guy who was here before, or are you one of those eight-legged cowards?  I need to know whether or not I should smack you on my way out.", sourceObjectiveStatus = "unverified-source-field" }
quests[27369] = { id = 27369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greasing the Wheel", description = "Sorry about that.  I was pretty sure you were one of those spider-beasts, doing a bad {race} impression.\n\nHow do you do?  Gidwin Goldbraids, at your service.  I'm in a bit of a hurry back to my caravan, but I was wondering if you might do me one last favor?  My pal Fiona runs a small shop, and she could probably use some of these herbs that grow along the river shore.\n\nI'm thinking if we give her some nice herbs, she'll be MUCH less likely to murder me.  That's the plan, anyway.", sourceObjective = "Loot 10 Banshee's Bells from the shore of the Thondroril River.", progress = "Giddy's got you mixed up in all of this now?", completion = "I'll tear that pint-size paladin to shreds before he... wait a minute are those Banshee's Bells?  You brought these for me?\n\nOh, Gidwin asked you to get them for me!  That sweet little guy.  Alright.  He's off the hook for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[27370] = { id = 27370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarenar Sunstrike", description = "As soon as we stopped, they made a bet about \"who could kill the most undead in five minutes.\"\n\nIt's been an hour, and I'm still waiting for them to come back.\n\nI saw Tarenar run off to the southeast.  Unfortunately, I can't leave the caravan here by itself.  If you end up traveling in that direction, could you find him and send him back to me?", sourceObjective = "Find Tarenar Sunstrike at Death's Step in Eastern Plaguelands.", completion = "I've found them, {race}.  The Scourge.  How I've longed for this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[27371] = { id = 27371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What I Do Best", description = "I remember when I was young, I would sneak off into the Ghostlands and just beat up zombies for hours on end.  Nobody even PAID me.  I just did it.\n\nNow, look in front of you.  Those are some serious zombies.  I was just about to start beating them up, too.  Care to join me?", sourceObjective = "Kill 5 Death's Step Miscreations at Death's Step in Eastern Plaguelands.", completion = "Five should be good enough.\n\nYikes, look at the time!  I need to head back to camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[27372] = { id = 27372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Fiona", description = "My traveling companion, Fiona, runs a small vendor's shop out of her caravan.  She and I, along with our friend Gidwin, are all on our way to Light's Hope Chapel.  I'm sure you can join us, if you like... though Fiona might be a little mad at me.\n\nFiona always forgets why she's mad if you give her a gift.  Kill some of the plaguehounds north of here, then bring their blood to Fiona at the caravan, down by the river.  She'll love it.  We'll talk again there.", sourceObjective = "Obtain 10 samples of Plaguehound Blood.", progress = "I should have guessed it.  Tarenar made you get me a gift?  That thoughtless idiot!\n\nUmm... what was the gift, anyhow?", completion = "Why, this is exactly what I needed!  Fine, I'll forgive Tarenar for running off.\n\n{name}, you're welcome to join us anytime.", sourceObjectiveStatus = "unverified-source-field" }
quests[27373] = { id = 27373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward, to Light's Hope Chapel", description = "Now that the boys are back, we can head out.  You headed east?\n\nPlease, join us!  I insist!  Yesterday, we were in the Menders' Stead, and I was telling Tarenar, \"We have two paladins and a shopkeeper, but you know what we really need?  A {class}!\"\n\nDon't look at me that way!  I'm serious!  Come on, hop in the cart.", sourceObjective = "Board Fiona's Caravan at the Thondroril River in Eastern Plaguelands.", completion = "Hope the ride wasn't too bumpy for you.\n\nHave a look around the tower while the horses rest.  It's no Light's Hope Chapel, but I'm sure you can find some way to keep yourself busy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27374] = { id = 27374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maw of Madness", description = "I can't believe it, {name}. Me own son - me own flesh and blood! Throwing his lot in with those fiends from the Twilight's Hammer. Did you see what he became when he tried to destroy the wedding? Oh ... why? Why?\n\nIt's that beast, {name}. The enormous mouth emerging from the earth to our west. \"The Maw of Madness!\" My son said it spoke to him, but I thought it was just nightmares.\n\nThe Earthen Ring is trying to destroy it. Go to Earthcaller Torunscar, west of here, and see how you can help!", sourceObjective = "Speak to Earthcaller Torunscar at the Ring of the Elements.", completion = "Welcome, brotha. You've chosen a harsh time to be joinin' us, but that is to our fortune. We could use ya help.", sourceObjectiveStatus = "unverified-source-field" }
quests[27375] = { id = 27375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weeping Wound", description = "A beast, {name}! I saw a beast. A great maw, an even greater hungering. They can't possibly know what they unleashed.\n\nIt is here. Its terrible shapeless body is erupting right into the Highlands.\n\nI saw you in my vision, {name}. You struggle with the Earthen Ring to contain the beast. You will face the darkness.\n\nGo now, before the beast grows in power. Speak to Earthcaller Torunscar at the Circle of the Elements, northwest of here atop the ridge beyond the ruined Drakgor Encampment. Hurry!", sourceObjective = "Speak with Earthcaller Torunscar at the Ring of the Elements.", completion = "Welcome, brotha. You've chosen a harsh time to be joinin' us, but that is to our fortune. We could use ya help.", sourceObjectiveStatus = "unverified-source-field" }
quests[27376] = { id = 27376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maw of Iso'rath", description = "We are ready to attack the beast. First, we need to destroy it's tentacles, then Yevaa will perform a ritual to summon a powerful fire elemental that we will drop into its maw.\n\nI want you to fly out with our first group attack. Hold steady until an opportunity presents itself, then join the battle with the rest of the shaman in cutting the tentacles down.\n\nTake any one of the gryphons when you're ready to join the assault.", sourceObjective = "Mount a gryphon to join the attack on Iso'rath.", progress = "You were to meet at the gryphons. Please stick to the plan.", completion = "The tentacles swept us off of our gryphons as well! They were far more nimble than we anticipated.\n\nNo matter. We were prepared for this possibility. I can summon the elemental from here if you can keep me safe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27377] = { id = 27377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devoured", description = "We knew this was a possibility, but we had no idea how the beast would defend itself. Iso'rath's body is reacting quickly to our threat.\n\nI can complete the summoning from here, but only if you can hold back Iso'rath's defenses. Keep them busy! We will survive this!", sourceObjective = "Defend yourself and Earthcaller Yevaa from Iso'rath's bodily defenses.", completion = "I've brought you back from the brink of death, hero!\n\nDeathwing is upon us! We need your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[27378] = { id = 27378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Worldbreaker", description = "There's no time! Deathwing struck before we could form against him. If you do not stop him, the Earthen Ring will end this day!", sourceObjective = "Defeat Deathwing, the Aspect of Death.", completion = "You're awake! Thank the elements. I'd almost lost all hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[27379] = { id = 27379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Terrors of Iso'rath", description = "We need you! You were stuck in some kind of nightmare. So are many of the other shaman.\n\nIt doesn't matter... our plan is falling apart. Some of our shaman are channeling protective auras that should combat the digestive juices and keep you alive, but we need you to rescue the other shaman from the tentacles.  We won't be able to defeat Iso'rath without them!\n\nDon't stay out in the stomach without the other shaman for too long or you'll be digested alive!", sourceObjective = "Rescue Hargoth Dimblaze, Earthmender Duarn, Stormcaller Jalara, and Stormcaller Mylra.\n\nReturn to the safety of the other shaman if Iso'rath's defenses are eating away at you.", progress = "The battle is not over. The shaman within Iso'rath need you!", completion = "United with the Earthen Ring, we can survive the horrors of Iso'rath. Now it is time to turn our vengeance upon him!", sourceObjectiveStatus = "unverified-source-field" }
quests[27380] = { id = 27380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmare", description = "Iso'rath's brain is revealed! The shaman you've saved should keep you somewhat safe amidst his defenses.\n\nStrike at the brain and destroy Iso'rath!", sourceObjective = "Destroy the Brain of Iso'rath.", completion = "You saved many of my closest allies today, {name}. I can only imagine what horrors you witnessed within Iso'rath, but you have the thanks of all of the Earthen Ring.", sourceObjectiveStatus = "unverified-source-field" }
quests[27381] = { id = 27381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traveling Companions", description = "While we're waiting here at this tower, we might as well see if anybody else is headed to Light's Hope Chapel.  The more, the merrier, I say!\n\nAsk around to see if anybody wants to join us on our trip.  I'm sure you can find somebody who's headed to Light's Hope.", sourceObjective = "Find someone at Crown Guard Tower who will join your caravan.", progress = "Any luck?", completion = "Argus Highbeacon... that old guy on the top of the tower?  Great!\n\nA man his age must have been in the Argent Crusade for a long time.  Maybe he can put in the good word for us at Light's Hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[27382] = { id = 27382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rough Roads", description = "The Argent Crusade built these towers to be points of light in the darkness of the Plaguelands.  I walk the paths between these towers, protecting and maintaining them.\n\nThe roads have been dangerous lately.  Plagued wildlife runs rampant, and bats swoop down upon unsuspecting travelers.  It would make the next leg of my journey much easier if you could clear some of this wildlife out of the way for me.", sourceObjective = "Slay 13 Plaguebats along the path to Light's Shield Tower.", completion = "Of course a young {race} like you would have no trouble taking care of a few wild animals.  With the roads clear, my journey to the next tower will be much easier.", sourceObjectiveStatus = "unverified-source-field" }
quests[27383] = { id = 27383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Pamela", description = "The battle for Darrowshire still haunts me, {race}.  I wake up in cold sweats, convinced that I'm still there; that it is happening all over again.\n\nI've coped with the loss of my comrades, but the loss of my family members is still cripplingly painful.  One of my kin lost during the attack was my young niece, Pamela.\n\nIf you are brave enough to enter Darrowshire, will you search for any sign of Pammy?  Darrowshire's ruins are due south of here.", sourceObjective = "Find Pamela Redpath in Darrowshire.", completion = "Hello.  I'm Pamela, what's your name?", sourceObjectiveStatus = "unverified-source-field" }
quests[27384] = { id = 27384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamela's Doll", description = "My auntie Marlene told me to stay here in our house because my father had to go and fight.  My father's the bravest man in the whole world!\n\nBut I've been here for a long time, and he hasn't come for me.  Sometimes bad people come and whisper to me and I want my dad to make them go away, but he's not here!\n\nAnd sometimes when it gets dark I want to play with my doll but I can't because I left it in town.\n\nWill you find my doll for me?", sourceObjective = "Find Pamela's doll.", progress = "Did you find my doll?", completion = "You found it!  You found my doll!  Oh, thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[27385] = { id = 27385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncle Carlin", description = "I'm going to play with dolly, but I don't want to play with daddy's sword after all.  You'd better keep it.\n\nEven better, can you give it to my uncle Carlin?  I'm not sure where he is, but sometimes I hear him crying.  It sounds like he's nearby, to the north.\n\nI hope he's not crying for me!  {name}, will you find my uncle and tell him I'm alright?\n\nIf you find him say I'm waiting for him, and I want to hear the story he used to tell... the one about the rabbits and the berry jam!  That story's so funny!", sourceObjective = "Return to Carlin Redpath at Crown Guard Tower in Eastern Plaguelands.", progress = "Any news of my Pammy?", completion = "You've seen Pamela?  She's alive?\n\nShe's dead?  No!  Oh, Pamela!  Why does your spirit still suffer in this world?  Why are you perished, while fortune keeps me alive?  In an instant I would switch places with you and wander dead Darrowshire, a ghost and alone!\n\nAh, but this news cannot change fate.  Thank you, {name}.  Now my duty, my duty to revenge, burns hot as ever.\n\nSay, what is that sword you have there?", sourceObjectiveStatus = "unverified-source-field" }
quests[27386] = { id = 27386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Historian", description = "That sword belonged to Joseph Redpath, Pamela's father - though you probably already knew that.  I wish Joseph could again be with his daughter, but it cannot be so.  His soul was twisted by the Scourge, and he became a monster.\n\nPamela's fate is sealed, but perhaps we can change Joseph's fate.\n\nA strange gnome arrived here at this tower not long ago.  Her name is Chromie.  Take that sword to her.  I have a feeling she will be able to help us.", sourceObjective = "Bring Joseph's Hunting Blade to Chromie.", progress = "There is something timely about your visit.  You're not from the future, are you?", completion = "What is this?  A warsword?  A butter knife?  I'm useless when it comes to blades.  Let me see...\n\nAh!  This sword was once in the hand of a great man, but there is much tragedy in that man's past.\n\nAre you here to help him?  It's far too late for him now... but perhaps we can help him in the past!", sourceObjectiveStatus = "unverified-source-field" }
quests[27387] = { id = 27387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Villains of Darrowshire", description = "The Annals of Darrowshire tells of the villains of that battle.  It tells how the ghoul lord Horgus the Ravager was destroyed by Alliance forces during the battle.  He was slain among the foothills north of here, and his skull remains there.\n\nMarduk the Black was never defeated, but his fabled sword now rusts, ownerless.  It can be found near the road to our southeast.\n\nRetrieve these items, {name}.  I know not why, but I am certain their fate lies with you.", sourceObjective = "Bring the Skull of Horgus and the Shattered Sword of Marduk to Chromie at Crown Guard Tower in Eastern Plaguelands.", progress = "Did you find the skull and the sword, {name}?", completion = "You found them!  Well done, {name}!  These relics hold within them the memories of the Scourge forces at Darrowshire.  We will need these if we are to save your Joseph Redpath.", sourceObjectiveStatus = "unverified-source-field" }
quests[27388] = { id = 27388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroes of Darrowshire", description = "The heroes of Darrowshire held relics of their own, and inside of those relics lie more precious memories.\n\nFirst, speak with Carlin and obtain the Extended Annals of Darrowshire.  Within the tome lies the narrative that will drive our excursion through time.\n\nThen, you will need to head west to the Marris Stead.  The former owner of the Marris farmhouse collected relics from the battle of Darrowshire - for what reason, I am not certain.\n\nGather these relics, and return to me.", sourceObjective = "Obtain the Extended Annals of Darrowshire from Carlin Redpath, and obtain Davil's Libram and Redpath's Shield from the Marris Stead.", progress = "Do you have the relics, {name}?", completion = "You have the relics?  Good.  I will get to work on resolving any temporal discontinuities.\n\nDon't worry... that's not something you have to worry about.  You just gather the reagents.", sourceObjectiveStatus = "unverified-source-field" }
quests[27389] = { id = 27389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marauders of Darrowshire", description = "I require a rare reagent for the powerful spell I intend to cast: skulls from the scourge who took part in the battle of Darrowshire.\n\nTake this crystal and hunt scourge champions for their skulls.  The crystal is enchanted; if a champion took part in the battle, then when you pass the crystal over its skull it will resonate.  Bring me those resonating skulls.\n\nGo, {name}.  You'll find scourge champions in the Fungal Vale to the north.  Go.", sourceObjective = "Bring 5 Resonating Skulls to Chromie at Crown Guard Tower in Eastern Plaguelands.", progress = "Do you have the skulls?  They are critical for my spell, which will give us the chance to save Darrowshire.  Maybe.", completion = "Excellent work, {name}.  Are you certain you haven't done this before?", sourceObjectiveStatus = "unverified-source-field" }
quests[27390] = { id = 27390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Darrowshire", description = "Now, {name}, you will take part in battle of Darrowshire, and you will save Joseph Redpath.\n\nPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.\n\nAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela.", sourceObjective = "Place the Relic Bundle at the Darrowshire town square.\n\nPrevent Davil Lightfire's death until the death of Horgus.\n\nPrevent Captain Redpath's death until Redpath the Corrupted appears.\n\nDefeat Redpath the Corrupted.\n\nSpeak with the spirit of Joseph Redpath when he appears at the town square.", progress = "I think I heard ghosts outside.  They whisper scary things to me...", completion = "The fighting is over!  I heard my daddy whisper to me.  He scared away all the ghosts and he says he's coming home!  I'm so happy!\n\nHe also said I should welcome you if you came to our house, so I made some tea!\n\nI hope you like lots of sugar!", sourceObjectiveStatus = "unverified-source-field" }
quests[27391] = { id = 27391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Treasures", description = "Daddy told me to give you this key.  He said it opens a chest out back behind the house.\n\nHe also wanted me to thank you.  Did you do a favor for him?  Did you tell him you found my doll?\n\nWell here's the key.  And thank you {name}.  Thank you!  You're a very nice <man/lady>!", sourceObjective = "Bring Joseph's Key to Joseph's Chest.", progress = "This chest is old and covered in grime.", completion = "The key fits the lock, and the chest opens...", sourceObjectiveStatus = "unverified-source-field" }
quests[27392] = { id = 27392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Not Supposed to Tell You This", description = "My daddy always kept two swords: one for fighting with men, and one for hunting the animals.  I wasn't supposed to touch his swords, but I knew where he hid them.\n\nOne day, he told my mommy that he was going to fight a \"lone hunter\" in the hills to the east, but he brought his animal sword with him!  When he came back, he didn't have his sword with him.\n\nWhen daddy comes back, he'll be so happy when I give him his animal sword!  Will you go and find it?", sourceObjective = "Obtain Joseph's Hunting Blade from The Lone Hunter in Eastern Plaguelands.", progress = "Daddy loved his animal sword.  He seemed sad when he didn't have it anymore.", completion = "That's my daddy's sword!  How did you find it?  Did you find the bad hunter?", sourceObjectiveStatus = "unverified-source-field" }
quests[27393] = { id = 27393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Blade", description = "I sense a strong power calling to me from the ruins. Can you check again on that southern battle site for me?  I'm certain that there's something there.", sourceObjective = "Investigate the battle site at the southern end of the Ruins of Vashj'ir.", completion = "The Wavespeaker was right. There's something here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27394] = { id = 27394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Blade", description = "I sense a strong power calling to me from the ruins. Can you check again on that southern battle site for me?  I'm certain that there's something there.", sourceObjective = "Investigate the battle site at the southern end of the Ruins of Vashj'ir.", completion = "The Wavespeaker was right. There's something here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27395] = { id = 27395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marksman's Weapon", description = "You have picked up the ways of the hunter quickly, {name}. Your skills have made you a credit to the Horde and an example to the younglings.\n\nAs a reward for your progress and hard work, the warchief has commissioned his personal bowyer to create a unique weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials we'll need. Travel there and retrieve the scope from Lord Godfrey's gun, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Godfrey's Crystal Scope, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I'm honored that the warchief chose me to craft a weapon for you, {name}. With such exotic materials, it will be a very fine bow.", sourceObjectiveStatus = "unverified-source-field" }
quests[27396] = { id = 27396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blade of the Shattered Hand", description = "Many members of the Shattered Hand do not survive their training, {name}. Not only have you survived, but you will soon become a feared blade of the Horde.\n\nAs a reward for your progress, the warchief has commissioned his personal smith to forge a weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover Commander Springvale's sharpening stone, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Springvale's Sharpening Stone from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Gordul told me that you would be bringing a variety of unusual materials, but I didn't expect anything like this. Moonsteel is said to be very rare and there's only one place I know to get it. You have risked much for this weapon, {name}, and I'll see to it that you receive a fitting reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[27397] = { id = 27397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreamseeker's Task", description = "The elements and spirits speak to you with clear voices, {name}. You have become a powerful shaman and an example to others wishing to serve the Horde.\n\nWord has even reached the warchief, and he has commissioned his personal smith to forge a special weapon for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and obtain Lord Walden's talisman, the Book of Lost Souls, and essence from the ghosts haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Walden's Talisman from Lord Walden, the Book of Lost Souls, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ah, you must be {name}. Kardris said that you were venturing to Shadowfang Keep to find the materials needed for this weapon and I see that you have not disappointed. I will make you a mighty weapon worthy of what you have brought.", sourceObjectiveStatus = "unverified-source-field" }
quests[27398] = { id = 27398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Is Won, The War Goes On", description = "We've defeated the enemy's forces here, {name}.  But Hyjal is not the only place where our foes are moving against us.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City for further instructions.", sourceObjective = "Speak to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.", completion = "Your aid is most timely, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27399] = { id = 27399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Is Won, The War Goes On", description = "We've defeated the enemy's forces here, {name}.  But Hyjal is not the only place where our foes are moving against us.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Farseer Krogar at the Western Earthshrine in Orgrimmar for further instructions.", sourceObjective = "Speak to Farseer Krogar at the Western Earthshrine in Orgrimmar.", completion = "Your aid is most timely, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27400] = { id = 27400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Arcane", description = "All of your trainers agree, {name}, you show an amazing amount of talent for a journeyman. Even the warchief has heard of your rapid progress.\n\nAs a reward for mastering your studies, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find a magical heirloom of the Silverlaine family, a supply of moontouched wood, and the essence of the ghosts haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Silverlaine's Enchanted Crystal from Baron Silverlaine, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ah, you must be the {class} that Uthel'nay mentioned. I've heard tales about the artifacts the Silverlaine family once kept, but I haven't ever seen one. This should make an excellent focus for your staff. Let's get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[27401] = { id = 27401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Tomorrow Brings", description = "<The F.C.D. buzzes.>\n\nLook around the Cathedral Quarter. There should be a telescope nearby that the 7th Legion uses for spying. Find it and use it to scout the harbor. We need to find out how the 7th Legion got past our fleet.\n\nHurry, {name}. We can't hold these beasts back much longer.\n\nWhat does tomorrow bring?", sourceObjective = "Use the 7th Legion Telescope to Scout the Harbor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27402] = { id = 27402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Token of Power", description = "Your mastery of our ways continues to grow quickly, {name}, and I am far from the only one impressed by your progress. Even the warchief has taken note of your deeds.\n\nAs a reward for your dedication, the warchief has commissioned his personal enchanter to craft a staff.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and retrieve the tenebrous orb held by Lord Godfrey, the Book of Lost Souls, and the essence of the ghosts haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Tenebrous Orb from Lord Godfrey, the Book of Lost Souls, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "So you are the {class} who will receive this staff. It will be a fitting reward for one so dedicated to the pursuit of power and the ascendancy of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27403] = { id = 27403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A True Sunwalker", description = "I have watched your training, {name}. Yours is the path of an exemplary Sunwalker, a brave defender of the Horde and a follower of our ways.\n\nAs a reward for your dedication, the warchief has commissioned his personal smith to forge a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I haven't worked with the Sunwalkers before, but from all I've heard, the warchief holds you in high regard. It was a great honor to be asked to forge this weapon for you and I hope it will serve you well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27404] = { id = 27404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Circle's Future", description = "The Cenarion Circle is pleased with your progress, {name}. You are a credit to all druids and we look to you and your peers as the future of our brotherhood.\n\nThe circle has decided to honor you with the creation of unique staff.\n\nThe rare and powerful materials needed for your staff can only be found in Shadowfang Keep inside Silverpine Forest. Travel there and retrieve Lord Walden's collection of elixirs, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Walden's Elixirs from Lord Walden, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your staff?", completion = "Ah, you must be the {class} Loganaar was talking about. It is a pleasure to finally meet you, {name}. I've often heard members of the circle describe you as a talented and promising {class} and I'm heartened to see their estimations were correct.", sourceObjectiveStatus = "unverified-source-field" }
quests[27405] = { id = 27405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fall Back!", description = "<The F.C.D. buzzes.>\n\n<Howls can be heard in the background.>\n\n{name}, do you read me? Come in, {name}. This is likely my final transmission. The worgen have overrun Forsaken Forward Command. It is now only a matter of time before the base is lost. Belmont and the val'kyr, Arthura, have left. Belmont mentioned that they will rendezvous with you at Emberstone Village, located to the northeast. Find Belmont, {name}. Our mission - our very existence - depends on it.\n\nYou are our final hope.", sourceObjective = "Find Deathstalker Commander Belmont at Emberstone Village in the Ruins of Gilneas.", completion = "Forward Commander Onslaught fought until the bitter end, {name}. It took a pack of bloodthirsty worgen to finally bring him down. We must not let his death, or the death of all of our soldiers in Gilneas, go in vain. Our mission MUST succeed.\n\nNow I will reveal to you why we are here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27406] = { id = 27406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Man Named Godfrey", description = "Lord Vincent Godfrey spent his life defending the kingdom of Gilneas. When the worgen curse ravaged this land, Godfrey was one of the first Gilneans to take up arms against the beasts. It is said that upon discovering that his king was afflicted by the curse, Godfrey took his own life. He would rather be dead than serve the very creatures that he had defended his home against.\n\nWe are going to give him a second chance, {name}. Together we will battle southeast towards Tempest's Reach to collect his corpse.", sourceObjective = "Find the corpse of Lord Vincent Godfrey.", progress = "Lord Vincent Godfrey. The name itself evokes feelings of dread in the hearts of worgen.", completion = "Here we are, {name}. He is a little rotted, but no worse for the wear. We must hurry before the Alliance finds us!", sourceObjectiveStatus = "unverified-source-field" }
quests[27407] = { id = 27407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodfen Feathers", description = "Are you startled by Brogg's presence here, little {race}? Don't worry. Goblins at Mudsprocket are Brogg's friends and you can be, too.\n\nBrogg left Brackenwall Village when new overlord not take revenge against black dragonkin for destroying old home and killing many of Brogg's old friends. Brogg come here to lay friends spirits to rest and avenge them, but Brogg need help preparing. For ritual, Brogg need feathers with strong magic, like ones worn by raptors at Bloodfen Burrow to the west of town.", sourceObjective = "Collect 5 Bloodfen Feathers from Bloodfen Raptors.", progress = "<Brogg looks at you hopefully.>\n\nYou bring Brogg feathers?", completion = "<Brogg accepts the feathers.>\n\nBrogg pleased with these feathers. Very strong magic. Brogg not know what raptors do to give feathers power, but raptor feathers always best for ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27408] = { id = 27408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banner of the Stonemaul", description = "When the dragons came and took over Brogg's old home, Stonemaul ogres fled and left everything behind, including clan's banner.\n\nBrogg knows banner was kept deep in Stonemaul ogre mound, but these days it's called Den of Flame. Brogg must have clan banner to get his revenge on dragons who killed his friends.\n\nBrogg's clan's old mound, Den of Flame, is northwest of Mudsprocket and crawling with dragonkin. Banner will be deep inside the cave. Be careful, {name}.", sourceObjective = "Retrieve the Stonemaul Banner from within the Den of Flame.", progress = "You bring Stonemaul banner?", completion = "You have Brogg's thanks, {name}. Brogg has big plans for clan banner.", sourceObjectiveStatus = "unverified-source-field" }
quests[27409] = { id = 27409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of Enmity", description = "To make the totem Brogg will need for his ritual, he must use the essences of the creatures who killed his friends. The hate and anger of Brogg's enemies will fuel the magic of his vengeance.\n\nTrack down Firemane ash tails, scouts, or scalebanes and use Brogg's totem on their corpses. Only when the dragonkin die will they give up their essences.\n\nThe creatures you seek swarm over the Den of Flame to the northwest and the Stonemaul Ruins to the north.", sourceObjective = "Bring 10 Black Dragonkin Essences to Brogg at Mudsprocket.", progress = "Do you have the essences? Brogg must have them to avenge his friends!", completion = "You have Brogg's thanks, {name}. Once Brogg adds their magic to the totem, it will be able to redeem the spirits of Brogg's fallen friends.", sourceObjectiveStatus = "unverified-source-field" }
quests[27410] = { id = 27410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of Stonemaul Hold", description = "Brogg has completed the totem that will put the spirits of his friends to rest. When the dragonkin came, they killed all Stonemaul who did not flee. Brogg fled with Overlord Mok'Morokk, hoping to lead a counterattack with other Stonemaul survivors.\n\nThe counterattack never came and the spirits of the Stonemaul dead still haunt Brogg and the others. Take this totem north to Stonemaul Ruins and use it near ogre skeletons to draw the spirit to you. Defeat the spirit to give it rest with its bones.", sourceObjective = "Put 10 Stonemaul Spirits to rest at the Stonemaul Ruins.", progress = "Brogg must know, have you brought peace to the violent spirits of the Stonemaul?", completion = "Brogg thanks you for your help, although he knows Overlord Mok'Morokk never will. At least surviving Stonemaul can finally focus on problems with the living and leave dead where they belong. Only one thing remains for Brogg to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[27411] = { id = 27411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge to the Black Flight", description = "Brogg relishes the thought of taking his revenge on the black dragonkin of the marsh. {name}, you have been very helpful in preparing for this moment. Will you help?\n\nTake Brogg's clan banner and travel east until you see a cave like a dragon's mouth. At the entrance to that cave, plant Stonemaul banner and issue Brogg's challenge to Onyxia.\n\nBrogg and the Stonemaul will have their lands back!", sourceObjective = "Plant the Stonemaul Banner near the entrance to Onyxia's Lair and defeat anyone who answers.", progress = "Brogg will have his revenge!", completion = "<Brogg listens as you recount your experience at the entrance to Onyxia's lair.>\n\nBrogg know Onyxia dead. Brogg know her brood still there. Brogg not let them forget the Stonemaul.\n\nBrogg is grateful for your help, {name}, and he will never forget what you have done for him. Brogg will never give up his quest to bring Stonemaul back where they belong.", sourceObjectiveStatus = "unverified-source-field" }
quests[27412] = { id = 27412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Goreclaw the Ravenous", description = "Travelers and Steamwheedle personnel working in the field are advised to avoid the Bloodfen Burrow to the west of town.\n\nThe area is overrun with raptors lead by the cruel and cunning Goreclaw the Ravenous, who has already killed at least two Steamwheedle engineers.\n\nDrazzit Dripvalve has authorized a generous reward to be paid to the individual who rids Mudsprocket of this menace.", sourceObjective = "Kill Goreclaw the Ravenous and report to Drazzit Dripvalve at Mudsprocket.", completion = "Thank goodness someone's finally taken me up on that offer. I was just thinking that I might need to triple the reward to get that stupid raptor killed, and our budget couldn't afford that!", sourceObjectiveStatus = "unverified-source-field" }
quests[27413] = { id = 27413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch a Dragon by the Tail", description = "With the zeppelin crash delaying supplies, we've run out of medicines and bandages.\n\nWe're making use of what we can, but between all the insects, the injuries, and the enemies we're encountering here, I can barely keep up! I've found one herb that seems to help heal wounds and dull pain, but it, too, is in short supply.\n\nIt's called wyrmtail, and it's abundant in the Dragonmurk and Wyrmbog areas east of town. The plants themselves are made of coiled stalks, and seem to pulsate when you look at them.", sourceObjective = "Collect 8 Wyrmtail stalks in the Dragonmurk or Wyrmbog.", progress = "Did you find any of the wyrmtail?", completion = "Thank you! This will help keep our guys going out in the field until Moxie returns with the rest of the supplies from the zeppelin crash.", sourceObjectiveStatus = "unverified-source-field" }
quests[27414] = { id = 27414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Identifying the Brood", description = "Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home.\n\nWhy the puzzled stare, {name}? Expecting me to speak like an uncouth ruffian merely because I am an ogre?\n\nNow back to business, bring to me the hearts and tongues from the whelps and hatchlings. I shall trace the root of this evil...", sourceObjective = "Draz'Zilb in Brackenwall Village would like you to bring him 7 Searing Tongues and 7 Searing Hearts.", progress = "With the hearts and tongues of scorched offspring of the black dragon army, I can decipher what wretched beast introduced her spawn into our home. Perhaps with a greater knowledge of our aggressors, we can seek to destroy them once and for all and reclaim Stonemaul Village from ruin.\n\nOf course, convincing Mok'Morokk to move his lethargic, fat mass out of this muck hole is going to be an epic quest in and of itself...", completion = "'Twas a perilous affair, no doubt, collecting all of these hearts and tongues. I shall delve into the depths of the arcane to trace the origin of the black menace which has descended upon our former home.", sourceObjectiveStatus = "unverified-source-field" }
quests[27415] = { id = 27415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood of Onyxia", description = "Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch.\n\nMake haste to Wyrmbog in the south of Dustwallow Marsh. Surely, she has made her lair there. Track down the evil dragon's eggs and destroy them.\n\nWe will never reclaim Stonemaul Village if the surrounding area remains a breeding ground.\n\nAs for Mok'Morokk... I have other plans for the sod.", sourceObjective = "Destroy 5 Eggs of Onyxia.", progress = "You must hurry to the Dragonmurk, {name}. With Onyxia's eggs riddled around the Wyrmbog, we face overwhelming numbers unless something is done quickly.\n\nDestroy her eggs! Don't let the black dragon plague spread across our homeland!", completion = "Splendid! It will be sometime before Onyxia can produce more eggs.\n\nOn behalf of my people, I thank you, {name}.\n\nI have asked much of you so far. Perhaps you can do the Stonemaul Clan one last service.\n\nMok'Morokk is not fit to lead us. Tharg would make an excellent leader but is hindered by his injuries and age. Drive Mok'Morokk from this place by force. Only then can we appoint a new leader to return us to our proper home in the south.", sourceObjectiveStatus = "unverified-source-field" }
quests[27416] = { id = 27416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood of Onyxia", description = "Stonemaul Village was invaded by the brood of Onyxia. But why would the daughter of the black dragonlord, Deathwing, descend upon our lands?\n\nThis is most troubling. Surely, Onyxia was driven here for a purpose beyond laying siege to a small band of ogres.\n\nNotify Mok'Morokk at once! Action must be taken.", sourceObjective = "Speak with Overlord Mok'Morokk in Brackenwall Village.", completion = "Why you tell me 'bout dragons? Me no like dragons. Me like it here. No dragons here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27417] = { id = 27417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood of Onyxia", description = "You leave me alone now. Go tell Draz'Zilb we stay here. No black dragon here.", sourceObjective = "Speak with Draz'Zilb in Brackenwall Village.", completion = "That lazy coward!\n\nMok'Morokk displayed strength when Rexxar was our leader. But soon after Rexxar's departure Mok'Morokk fell prey to temptations of power. Rather than lead, he demanded. He does not serve his people but rather expects us to serve him.\n\nSomething must be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[27418] = { id = 27418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge Overlord Mok'Morokk", description = "You dare challenge Overlord Mok'Morokk?\n\nHaw!\n\nMe crush tiny {race}!\n\nYou tell me when ready for good beating.", sourceObjective = "Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.", completion = "That cowardly fat mass Mok'Morokk fled like a scared child. You have done a great service, {name}.\n\nNow my people can appoint a new leader, one who will help us reclaim our old home once and for all.", sourceObjectiveStatus = "unverified-source-field" }
quests[27419] = { id = 27419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Army of the Black Dragon", description = "Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres.\n\nBlack dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here.\n\nOgre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk.\n\nMe call Stonemaul Ruins home. Me like it in the south. This place not home.\n\nHelp ogres fight army of the black dragon. Me want revenge. Me want to go home.You will be able to choose one of these rewards:", sourceObjective = "Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Scalebanes.", sourceObjectiveStatus = "unverified-source-field" }
quests[27420] = { id = 27420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postponing the Inevitable", description = "You have a keen eye to have seen me here, hidden among the grasses.\n\nAhead of us lies the Fungal Vale, an area that the Scourge still cling tightly to.  They use floating constructs to continually re-plague the land, keeping it vile and polluted.\n\nThe devices are controlled with runes, which are held by dark adepts and shadowmages.  Take the controlling runes that these cultists hold, aim them at the plague disseminators, then overcharge them with this mote.  The results should be amusing.", sourceObjective = "Obtain Control Runes from Dark Cultists and Shadowmages, then use the Overcharged Mote on them to destroy 3 Plague Disseminators.", completion = "The sooner those Scourge are pushed out of the Fungal Vale, the sooner we can heal it.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27421] = { id = 27421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amidst Death, Life", description = "Scourge forces have made it a point to ensure that nothing survives in the Fungal Vale - all you will find are husks of rotted mushrooms and scorched grasses.  The three corners of the vale are home to three large ziggurats, which they use to reanimate their dead and summon new soldiers to the battlefield.\n\nYet even in this evil, lifeless place, life finds a way to flourish.  Take my seeds and plant them in the centers of these ziggurats.  Prove to them that life will prevail.", sourceObjective = "Use Rayne's Seeds in the center of the three ziggurats in the Fungal Vale.", progress = "I am confident that nature will find a foothold within those ziggurats.", completion = "Even if the flowers died out shortly after they bloomed, they proved our point to the Scourge: they are losing, and we are winning.\n\nThank you for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27422] = { id = 27422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A City Under Siege", description = "We will never control the Eastern Plaguelands if we do not control Stratholme. Not only is it a point of incredible strategic importance, it also houses our enemies' leaders - Balnazzar and Lord Aurius Rivendare. Their Risen and Scourge armies threaten to erase all the progress we've made.\n\nThe Argent Crusade is well-suited to this task. Travel west through Stratholme's main gate and speak with Packmaster Stonebruiser. He will direct you further.", sourceObjective = "Speak to Packmaster Stonebruiser.", completion = "What a relief it is to see an able-bodied soldier that's on our side! There's plenty for ye to do around here, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27423] = { id = 27423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resistance is Futile", description = "<The F.C.D. buzzes.>\n\nThis is Commander Lorna Crowley of the Gilneas Liberation Front. If you are hearing this message then you know that the Alliance once again controls Gilneas. Lay down your weapons and surrender. Failure to comply will result in your death.\n\nOur forces have locked on to your position and will arrive shortly. Resistance is futile.", sourceObjective = "Kill 20 Worgen Combatants.", progress = "Surrender? Coward talk...", completion = "No time to bask in the battle glory, {name}. We have a job to do. I have no doubt more of those beasts are on the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[27424] = { id = 27424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overlord Mok'Morokk's Concern", description = "Bow before Overlord Mok'Morokk!\n\nRexxar make me mighty leader of Stonemaul Clan!\n\nMe good leader. Me keep clan safe.\n\nBig dragons come and make fire at old home. Me smart ogre. Find new home for clan here.\n\nLeave old home so fast, me forget stuff. Tiny {race}, go get my things. Go south and find my yummy grog, my snuff and my strongbox. Me like you after you do that. You look in Den of Flame and Stonemaul Ruins... they be there, me sure!", sourceObjective = "Collect Overlord Mok'Morokk's grog, snuff and strongbox from Dustwallow Marsh.", progress = "Me thirsty for grog. Me miss snuff too. Where is strongbox? You go get for Overlord Mok'Morokk.\n\nGo find south in old home. Me too busy leading ogres to get.", completion = "You good {race}. Me miss things very much. Me like you now.", sourceObjectiveStatus = "unverified-source-field" }
quests[27425] = { id = 27425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Connection", description = "I've spoken with Inspector Tarem regarding the evidence you gathered from the ruins of the Shady Rest Inn. He seems certain that the hoofprints and the shield you found there point to the Grimtotem clan of tauren.\n\nWith reports of Grimtotem activity on the rise in the marsh, this has to be more than a mere coincidence. I'm sending you to speak with Captain Darill, who is something of an expert on the Grimtotems. Follow the road north out of town to North Point tower. It's the second outpost on the road.", sourceObjective = "Report to Captain Darill at North Point.", completion = "Captain Vimes thinks the Grimtotems are behind the destruction of the Shady Rest Inn? They wouldn't have been first on my list of suspects, but if Captain Vimes sent you here to follow up on a lead, he must have his reasons. Regardless, the Grimtotems have been a thorn in our side for some time and we're always glad to have the extra help.", sourceObjectiveStatus = "unverified-source-field" }
quests[27426] = { id = 27426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confirming the Suspicion", description = "The Grimtotems may be the most warlike of all the tauren clans, but they're by no means unorganized. If they're the ones who put the torch to the Shady Rest Inn, they'll have had orders from one of their clan elders.\n\nThere's a large Grimtotem settlement called Blackhoof Village to the northwest. They've been using it as a base to attack the tower, but I'll bet that you'll find the orders you're looking for there. Check the village's elders for traces of the orders you seek.", sourceObjective = "Collect 4 Grimtotem Notes from Grimtotem Elders and combine them into the Grimtotem Battle Plan.", progress = "Were you able to find any trace of the orders?", completion = "<Captain Darill glances at the battle plan.>\n\nI'd say it doesn't get any clearer than this. They've taken it upon themselves to fight back against {race} settlements in the area and I have little doubt Theramore is next on their list.", sourceObjectiveStatus = "unverified-source-field" }
quests[27427] = { id = 27427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms of the Grimtotems", description = "If the equipment you found at the ruins of the inn belonged to a Grimtotem attack party, there's likely to be more just like it within their camp to the northwest.\n\nWe haven't been able to gather much information about Blackhoof Village, but judging from the size of the raiding parties, there's a substantial force based there.\n\nDo whatever you have to to capture some of their equipment so that we can compare it with your findings from the inn.", sourceObjective = "Captain Darill at North Point Tower wants you to bring him 7 Blackhoof Armaments.", progress = "Did you get those weapons from Blackhoof Village?", completion = "<Captain Darill inspects the armaments you've brought from Blackhoof Village.>\n\nThere's no doubt about it. These match the description exactly, but there's just one problem -- these have never been used in battle. Blackhoof Village must not be the only Grimtotem post in the marsh.", sourceObjectiveStatus = "unverified-source-field" }
quests[27428] = { id = 27428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabetha's Assistance", description = "I can't spare any men to help search for a second Grimtotem outpost, but I think I know of someone who might be able to help you.\n\nDeep in the Quagmire, to the south, there is a small farmstead owned by Tabetha. She may seem little more than an old hermit, but the truth is that she's a mage and scryer of some renown. Follow the road south to her farm and seek her help in finding the culprits responsible for the massacre at the Shady Rest Inn.", sourceObjective = "Speak with Tabetha at her farm.", completion = "So you want me to scry for Grimtotems, eh? And what will you say when I tell you there's no need?", sourceObjectiveStatus = "unverified-source-field" }
quests[27429] = { id = 27429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm, near the road. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", sourceObjective = "Use Tabetha's Torch to burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post.", progress = "Have you put that torch to good use?", completion = "I hope the Grimtotems got the message. Any attempt to return will be met with far worse than a mere torch. My apprentices and I will see to that.", sourceObjectiveStatus = "unverified-source-field" }
quests[27430] = { id = 27430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice for the Hyals", description = "Although these Grimtotems were simply a nuisance to me, Captain Vimes will want to know of your deeds. Bring him the news that you have tracked down and dealt with those responsible for the burning of the Shady Rest Inn.\n\nIt's too late to save Jim Hyal's family, but perhaps the Grimtotems will think twice before attacking anyone connected to Theramore.", sourceObjective = "Speak to Captain Garran Vimes at Foothold Citadel in Theramore.", completion = "<The captain listens to your report intently.>\n\nWe have avenged James and his family, but not even that can restore what was destroyed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27431] = { id = 27431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tipping the Balance", description = "<Harrison grins.>\n\nThat's it, {name}. The pieces we need are hidden in these statues!\n\nThey look to be a bit off balance as is. Maybe just a little nudge...\n\nI must say, your field work is coming along nicely. If you applied yourself, you could make a fine archaeologist one day.", sourceObjective = "Speak to Harrison Jones in the Chamber of the Stars.", progress = "What have you found, {name}?", completion = "Talk about bringing the house down...", sourceObjectiveStatus = "unverified-source-field" }
quests[27432] = { id = 27432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaeldarr the Outcast", description = "Can you believe that, after all the trouble we have in the Plaguelands... we have to worry about thieves too?  And not just normal thieves, troll thieves.\n\nAnd not just normal troll thieves.  Dead troll thieves!\n\nThey're led by this big, dead troll named Zaeldarr the Outcast, and they come here at night and steal bodies from our graveyards, then take them back to their evil, dead troll hideout--the Undercroft to the southwest.\n\nGo there and take out Zaeldarr, {name}.  I'm sick to death of his mischief!", sourceObjective = "Obtain Zaeldarr's Head from Zaeldarr the Outcast.", progress = "Did you find the hideout, {name}?  Did you take care of Zaeldarr?", completion = "Great, you got him!  And I hope you taught his gang a lesson too!", sourceObjectiveStatus = "unverified-source-field" }
quests[27433] = { id = 27433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredderectomy", description = "Our tanks have to pull back, and that means repairs in the field.\n\nSmash up summa them diamond-bladed shredders those wee green monsters are using to fell the trees along the coast, and bring me a heap of leftover shredder parts. We'll bang together sumthun' to get our tanks movin' again.", sourceObjective = "Destroy Diamond-Blade Shredders to collect 5 Abused Shredder Parts.", progress = "What'd you get me, {name}?", completion = "Oh aye, tha's the stuff! A good engineer can make anything outta just about anything.\n\nThis here doo-jicker could recouple a busted cylinder casing... Oh! And who doesn't want a dongle? ...And you can fashion this jobby into a ... thing.\n\n<Flintlocke sticks one of the grease-smeared engine parts into his mouth.>\n\nYep, perfect.", sourceObjectiveStatus = "unverified-source-field" }
quests[27434] = { id = 27434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Adept's Path", description = "Your time as an apprentice has come to an end, {name}. You are ready to advance to the rank of adept, to become a full blood knight in service to Silvermoon.\n\nTo honor your accomplishments, the warchief has commissioned his personal smith to forge a weapon for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists there.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I don't know how you came by such a large supply of moonsteel, {name}, but I haven't worked with it in years. It will be both a challenge and a pleasure to create this weapon for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27435] = { id = 27435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Seer's Staff", description = "In the eyes of the Earthmother, you are ready to become a full seer. You have completed your early training with skill and dedication.\n\nTo mark this occasion, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", sourceObjectiveStatus = "unverified-source-field" }
quests[27436] = { id = 27436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow-Walker's Task", description = "This be a great occasion, {name}. You've learned much and grown in de ways o' power. Your future be a great one for da Darkspear and da Horde.\n\nI asked da warchief's master enchanter to be makin' a staff for you to recognize all your achievements.\n\nTo get what you be needin' you'll have to travel to the cursed Shadowfang Keep inside Silverpine Forest. Find da holy symbol of Commander Springvale, a supply of moontouched wood, and da essence of the spirits that haunt da keep and bring dem to Godan.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", sourceObjectiveStatus = "unverified-source-field" }
quests[27437] = { id = 27437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Cleric's Bidding", description = "You have been a diligent student and servant to our cause. Always use your talents in accord with Lady Sylvanas's wishes and you will be blessed by the shadow.\n\nOur queen has arranged for Orgrimmar's master enchanter to create a powerful staff to recognize your service.\n\nThe materials you will need only come from Shadowfang Keep in the heart of Silverpine Forest. Find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Dark Cleric Cecille mentioned that you were visiting Shadowfang Keep to find the materials for your new staff. I see now why she sent you there. Even the twisted magics gripping the keep could not extinguish the power of these items.", sourceObjectiveStatus = "unverified-source-field" }
quests[27438] = { id = 27438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Escape", description = "With our mission objective secured, the time has come for us to make our escape. Though Gilneas is lost, with the aid of Godfrey and his lieutenants we will have it back in no time at all.\n\nGo now, {name}. Fly back with Arthura to the Forsaken Front in southern Silverpine Forest. The Banshee Queen awaits your arrival.", sourceObjective = "Escape the Ruins of Gilneas with Arthura and the corpse of Lord Godfrey.", completion = "I had no doubt that you would succeed, {name}. I hope you can understand why I kept the true purpose of your mission a secret. Should Crowley and Bloodfang have found out about our plan, they would have surely gotten to Godfrey first and disposed of the body.\n\nStand by, {name}. The time of their rebirth is at hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[27439] = { id = 27439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staff of the Light", description = "You are quickly becoming a talented servant of the Light and of Silvermoon, {name}. Your loyalty to our people and to the Horde are exemplary.\n\nIn recognition of your dedication, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Tyelis mentioned that you were visiting Shadowfang Keep to find the materials for your new staff. Few would venture into the keep, even to retrieve such valuable things. Your new staff will be a fitting reward for your bravery.", sourceObjectiveStatus = "unverified-source-field" }
quests[27440] = { id = 27440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolls, Ogres, and Orcs, Oh My!", description = "The black dragonkin Overlord Wyrmthalak oversees the forces of the Lower Spire, who are nearly prepared to launch a full assault on the Dark Iron Dwarves far below. We simply cannot allow the black dragonflight to gain control of the mountain!\n\nYou must kill War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Their deaths will cause the army's momentum to grind to a halt and will buy us valuable time.", sourceObjective = "Kill War Master Voone, Highlord Omokk, and Overlord Wyrmthalak.", progress = "These are not mindless beasts you are up against, {race}. It is a massive army backed by the ruthless black dragonflight. Exercise caution in these corridors.", completion = "Pardon my saying so, but I am surprised you completed the task set out before you alive. Those monsters were responsible for the deaths of countless thousands, a great many of them heroes still spoken highly of to this day.\n\nYou have earned my respect and a reward for your courage.", sourceObjectiveStatus = "unverified-source-field" }
quests[27441] = { id = 27441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Seer's Staff", description = "I hear that word of your deeds in service to the Horde has even reached the ears of the warchief. I think he might see the error of his earlier judgment about us.\n\nHe has agreed to allow Orgrimmar's master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "You must be the {class} that Brother Silverhallow mentioned. Welcome, {name}. Let me see those materials you gathered from halfway around the world. They seem well worth the travel and you will not be disappointed with your staff.", sourceObjectiveStatus = "unverified-source-field" }
quests[27442] = { id = 27442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Has Many Fronts", description = "We find ourselves in a much better position against our enemies in Vashj'ir than before you arrived.  Don't get me wrong, your aid is still needed here, but perhaps other fronts are in an even more urgent situation.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Farseer Krogar at the Western Earthshrine in Orgrimmar for further instructions.", sourceObjective = "Speak to Farseer Krogar at the Western Earthshrine in Orgrimmar.", completion = "Your aid is most timely, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27443] = { id = 27443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Has Many Fronts", description = "We find ourselves in a much better position against our enemies in Vashj'ir than before you arrived.  Don't get me wrong, your aid is still needed here, but perhaps other fronts are in an even more urgent situation.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Earthspeaker Naraat at the Eastern Earthshrine in Stormwind City for further instructions.", sourceObjective = "Speak to Earthspeaker Naraat at the Eastern Earthshrine in Stormwind City.", completion = "Your aid is most timely, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27444] = { id = 27444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The False Warchief", description = "Rend Blackhand was the son of an Orc Warchief. His father was slain by Orgrim Doomhammer, who became the new Warchief over the young orc. Rend now stands as the supposed leader of a false Horde of Blackrock orcs, backed by Nefarian and his army of dragons.\n\nThe fool claims that the Horde is also his by birthright, and threatens to take it by force! We cannot allow this to occur in light of his master's influence. Find him in the Upper Spire and bring an end to the false warchief, {class}.", sourceObjective = "Kill Warchief Rend Blackhand.", progress = "Rend will not fall without a fight.", completion = "You saw Nefarian when you fought Rend?\n\n<Acride sighs.>\n\nI wish I had accompanied you, then. I could have faced him unaware, outside his lair...but no matter. Nefarian will die by my claw.\n\nYou've done well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27445] = { id = 27445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Drakkisath, Hand of Nefarian", description = "Nefarian makes his domain further up the mountain in Blackwing Lair. Though there is a way in through the Upper Spire, we may bring a far larger force if we use the teleportation orb close by. However, we cannot teleport until we brand ourselves with a different orb.\n\nDrakkisath, General of Nefarian's armies, personally guards this second orb. Eliminate him and secure his orb for our use. You will find him in the Spire Throne within the Upper Spire.", sourceObjective = "Kill General Drakkisath.", completion = "Excellent! It is only a matter of time before the son of Deathwing feels my claws.", sourceObjectiveStatus = "unverified-source-field" }
quests[27446] = { id = 27446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaris is Calling", description = "Heya, {name}, Kelsey Steelspark down in Tanaris left a message for you. She says that the gnomes down there in Gadgetzan heard about what you've been doing up here.\n\nAnyway, the Cataclysm hit them hard, too. Not as hard as us, but I'm certain they could use your help.", sourceObjective = "Speak with Kelsey Steelspark at Gadgetzan in Tanaris.", completion = "Greetings and salutations, friend. Welcome to Tanaris!", sourceObjectiveStatus = "unverified-source-field" }
quests[27447] = { id = 27447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaris is Calling", description = "Heya, {name}, Megs Dreadshredder down in Tanaris left a message for you. She says that the goblins down there in Gadgetzan heard about what you've been doing up here.\n\nAnyway, the Cataclysm hit them hard, too. Not as hard as us, but I'm certain they could use your help.\n\nBesides, that Megs is a hottie!", sourceObjective = "Speak with Megs Dreadshredder at Gadgetzan in Tanaris.", completion = "Well hello there, {class}. Welcome to Tanaris!", sourceObjectiveStatus = "unverified-source-field" }
quests[27448] = { id = 27448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trek Continues", description = "I believe the horses are ready.  Argus Highbeacon, the gentleman who works with the Argent Crusade, spoke with me earlier.  I understand he will be coming with us... that's great!  I'll make room for him.\n\nI know that you are busy, so there's no hurry.  Whenever you're ready, hop into the caravan, and we will proceed to the next tower.", sourceObjective = "Board Fiona's Caravan when you are ready to move to the next tower.", progress = "Once we get to Light's Shield Tower, the boys can head over to Light's Hope Chapel.  It's close enough that they can walk.", completion = "We've enjoyed having you ride with us, {name}.  Hopefully, once Gidwin and Tarenar join the Argent Crusade, we can continue to travel together.", sourceObjectiveStatus = "unverified-source-field" }
quests[27449] = { id = 27449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor and Strength", description = "My name is Vex'tul, and I have watched you fight, {race}.  You are strong.\n\nYou killed my master, Zaeldarr, but this does not bother me.  I value strength over any loyalty that I held for him.  I value strength over anything else.\n\nProve to me one final time your strength, {race}.  Do so, and I will lend you MY strength for whatever purpose you may desire.", sourceObjective = "Pass Vex'tul's test of strength.", completion = "Yes, you are indeed strong... and I submit to you.\n\nI will join you and your friend, the worgen.  My strength is yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[27450] = { id = 27450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frederick's Fish Fancy", description = "I love the sea.  Yes, it was I, Frederick Calston, who introduced the sea life to that lake in the southwest.  I had hoped to provide the Crusade with a source of fresh food from within the borders of the Plaguelands.\n\nHowever, some of the fish turned out to be predators, and they now terrorize the other animals.  If we're not careful, they will kill them all!\n\nSwim down to the bottom of the scar and save some snails, crabs, and pufferfish before it's too late.", sourceObjective = "Obtain 8 Plague Puffers, 8 Infectis Inchers, and 8 Infectis Scuttlers from the Infectis Scar.", progress = "Did... did you bring the fish?", completion = "Hmm... they didn't survive the trip out of the water as well as I had hoped.\n\nOh well!  Seafood salad for Frederick tonight!", sourceObjectiveStatus = "unverified-source-field" }
quests[27451] = { id = 27451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Kill With Purpose", description = "Greetings, stranger!  You've entered the heart of the Plaguelands.  I hope you brought your undead-killing gear with you.\n\nThe plague spreads more slowly these days, so the Cult of the Damned has stepped up production in order to keep the land brown and dead, as they like it.  I've got a plan to stop them.  Take my mortar and pestle, and use it on living rot from the undead creatures in Corin's Crossing to the southeast.  We're going to make a little present for the cultists!", sourceObjective = "Travel to Corin's Crossing to the south and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.", progress = "How are things looking in Corin's Crossing?", completion = "Hello!  It's me.  Hope you don't mind a little home-brewed magic to allow me to communicate with you in the field.  It'll save us both some time.\n\nWe're going to incorporate that living rot into a mixture that'll ruin their next batch of plague.  That'll show them!", sourceObjectiveStatus = "unverified-source-field" }
quests[27452] = { id = 27452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Garb", description = "Some of my counterparts have told me that the land wants to heal, but several high-ranking undead - along with the Cult of the Damned - are not allowing it to.  That means we have to stop them!  I've got a plan, but first, you're going to need a cultist disguise.\n\nHead southeast into Corin's Crossing, and take the clothing from the human cultists that roam through the town.  I'll contact you when you've completed this step.", sourceObjective = "Obtain Death Cultist Headwear and Death Cultist Robes from cultists within Corin's Crossing.", progress = "Everything going alright so far, {name}?", completion = "You've got both pieces!  Good.  These will help when trying to sneak into their death camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[27453] = { id = 27453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catalysm", description = "Coagulated rot is potent on its own, but we need something to activate its concealed powers... a catalyst.  You can find just such a catalyst to the south, in Lake Mereldar.\n\nIf you look down, you'll notice that I slipped a set of flasks into your bags while you weren't looking.  These flasks can be used on the water elementals in the lake.  The living, corrupted water that flows through their bodies will be the perfect catalyst!", sourceObjective = "Use Betina's Flasks on living elementals within Lake Mereldar to obtain 8 Active Liquid Plague Agents.", progress = "We're nearly ready to strike, {name}.", completion = "Uh oh... it looks like we may have gathered a little too much coagulated rot.  Oh well, we'll just have to improvise, then!\n\nWhat could possibly go wrong?", sourceObjectiveStatus = "unverified-source-field" }
quests[27454] = { id = 27454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Drop in the Bucket", description = "Now, mix a tiny amount of rot into the water, and mix thoroughly.  There, that's it.  This solution will still be very powerful, and we only need a little bit of it.\n\nOn the lake's southeastern border, you will find a plague cauldron with several cultists nearby.  Put on your cultist disguise, then approach the cauldron and put in ONE DROP of the solution you made.  No more, or you may risk your very life!", sourceObjective = "Use your Death Cultist Disguise to enter the Death Cultist Base Camp, then put Betina's mixture into the Mereldar Plague Cauldron.", completion = "It should take them weeks to get their operation running again.  Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27455] = { id = 27455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boys Will Be Boys", description = "As soon as we arrived here at Light's Shield Tower, those two lunkhead paladins ran off to Light's Hope Chapel.  It's still a ways away, but if we're going to follow Argus along his tour of the towers, this is about as close as we're going to get.\n\nCheck in on them and make sure they're alright?  I know they can handle themselves, but still, it'd make me feel better to know that you were watching over them while I'm stuck here with the caravan.", sourceObjective = "Find Gidwin Goldbraids at Light's Hope Chapel in Eastern Plaguelands.", completion = "I can't believe it.  We're literally FEET away from becoming sworn members of the Argent Crusade.\n\nWe'd be in there already if it weren't for Tarenar's dallying.  If he doesn't quit chatting with the locals soon, I'm going to head in there myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[27456] = { id = 27456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Some Grub(s)", description = "We have problems maintaining our food supplies here in the far east.\n\nAround here, the only manner of beast unaffected by the ravages of the plague are the carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. We will need several hundred more pounds to be fully-stocked.\n\nWhile you can find carrion worms all over the Plaguelands, they can be found in particularly high density to the south of the chapel.  And remember: larger worms mean more meat.", sourceObjective = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest 15 Slabs of Carrion Worm Meat.", progress = "You will grow to tolerate the taste, {race}.  I did.", completion = "May the Earthmother watch over you! Bless you, young one.", sourceObjectiveStatus = "unverified-source-field" }
quests[27457] = { id = 27457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Opportune Alliance", description = "With your contributions to the food stores, my current assignment is complete.\n\nI will be heading north, to the Plaguewood, next.  I understand you may be headed in the same direction.\n\nDo you mind if I join you on the road?\n\nI will head northwest, to Eastwall Tower.  If you're interested in teaming up, you can meet up with me there.", sourceObjective = "Check in with Fiona at Eastwall Tower in Eastern Plaguelands.", completion = "You brought us a shaman!  From the Earthen Ring, no less!\n\nI have no idea how we'll fit him in the caravan, but we'll find a way.  Welcome aboard, Rimblat Earthshatter!", sourceObjectiveStatus = "unverified-source-field" }
quests[27458] = { id = 27458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smokey and the Bandage", description = "Hey there!  Interested in makin' a buck?\n\nI need to get a bandage.  Well, actually, I got a friend who needs to get a bandage.  Well actually... let's just say it's complicated, but if you go get this bandage, you make money.  And so do I.  And my friend.  Possibly other people.\n\nStephen Browman used to own the mill to the north, now he's dead.  A zombie.  The guy at the top wants to have the wrappings from Browman's body.\n\nWhat's the matter, you don't like money?", sourceObjective = "Obtain Browman's Wrappings from Stephen Browman at Browman's Mill.", progress = "You've been fightin' undead.  Did ya find Browman?", completion = "Well well well!  Someone who goes and gets things done!  Here's your cut, chief.  I'll be seein' you around.", sourceObjectiveStatus = "unverified-source-field" }
quests[27459] = { id = 27459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brotherhood of Light", description = "The Brotherhood of Light has a history of brash, thoughtless decisions.  They bridged a gap between the Scarlet Crusade and the Argent Dawn.  They were among the first to plunge into Northrend, while many of us lingered behind.\n\nHowever, they also have a history of getting results, which I respect.  They fight on two fronts now: one battle in Stratholme, and another, more immediate battle to the south at Tyr's Hand.\n\nI suggest you speak with Angela Dosantos at Tyr's Hand.  You may be of service.", sourceObjective = "Report to Archmage Angela Dosantos at Tyr's Hand in Eastern Plaguelands.", completion = "A {class}!  Just what we needed.  Your arrival couldn't have been more timely.", sourceObjectiveStatus = "unverified-source-field" }
quests[27460] = { id = 27460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soft Landing", description = "We were only given one hundred men to complete this mission, and we're already down by one.  Our scout was sent into the enemy stronghold to clear out some of the guards that patrol the area, and to send off a flare so we could enter with a coordinated attack.  Our ninety-nine remaining men lie at the ready, waiting for that flare.  I need a talented {class} like you to sneak into Tyr's Hand, take out as many of their guards as possible, and then set off that flare.\n\nAre you up to it?", sourceObjective = "Kill any 10 Scarlet Crusade creatures within Tyr's Hand.", completion = "The flare is fully assembled, and the matches lie unused next to the fuse.\n\nThe fallen Argent centurion got much closer to setting off this flare than you had guessed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27461] = { id = 27461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Take the Abbey", description = "The Scarlet Crusade maintains a well-fortified abbey in the lower western tier of Tyr's Hand.  The abbey will need to be secured before proceeding any further into the stronghold.", sourceObjective = "Report to Commander Eligor Dawnbringer outside the abbey at Tyr's Hand in Eastern Plaguelands.", completion = "Well met, {name}.  Can I trust you to assist me in taking this abbey away from these abominations?", sourceObjectiveStatus = "unverified-source-field" }
quests[27462] = { id = 27462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Take the Barracks", description = "One of the key fortifications within Tyr's Hand is the barracks, which lies right next to this flare.  The Brotherhood of Light and their centurions will need all the help they can get in sacking it.", sourceObjective = "Report to Crusade Commander Korfax in front of the Barracks at Tyr's Hand in Eastern Plaguelands.", completion = "I'll be handling things from here, {class}.\n\nFine, you want an assignment?  I suppose I can afford to send you in on a mission or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[27463] = { id = 27463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Boyhood Dream", description = "I've always wanted to join the Crusade.  It's the reason I became a paladin.  Years of practice, honing my craft... I'm finally ready.\n\nTarenar thinks he's ready, too, but I'm not sure.  He's a bit of a showboat, and he never took his lessons seriously.  Still, we promised we'd do this together, and here we are.\n\nShall we head into the chapel now?", sourceObjective = "Speak with Lord Maxwell Tyrosus within Light's Hope Chapel.", completion = "Welcome to Light's Hope Chapel.\n\nYou wish to join the Crusade?  Very well.  We have plenty of tasks for new recruits.\n\nBut first, a test.", sourceObjectiveStatus = "unverified-source-field" }
quests[27464] = { id = 27464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Call: The Trial of the Crypt", description = "Behind our chapel, you will find a small crypt.  Interred within are the bodies of our fallen heroes; those who gave their lives in the war against the Scourge.\n\nTheir spirits are at peace, but they return intermittently to test new members of the order.\n\nThe three of you may test together.  Enter the crypt, then read from this scroll.  Lord Raymond George - my predecessor - will preside over your test.", sourceObjective = "Enter the Crypt behind Light's Hope Chapel, read from the Argent Scroll, then complete his test.", progress = "Your test is not yet complete.", completion = "Remember that your ancestors always watch over you.  As a brother of the Argent Crusade, you will join a family that has a long line of such fallen ancestors.  Their vigil and protection will be your strength as you press forward against the Scourge.\n\nCongratulations Tarenar, Gidwin, and {name}.  Welcome to the Argent Crusade.", sourceObjectiveStatus = "unverified-source-field" }
quests[27465] = { id = 27465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Call: The Noxious Glade", description = "Browman's Mill, to the north, is infested with undead.  The Noxious Glade, even farther to the north, is even more heavily infested.  Despite their proximity to our chapel, we have been unable to completely remove them.\n\nVigilance is key.  Travel into the Noxious Vale and slay as many undead as you can find... and the cultists that roam among them.\n\nWhile there, make sure to avoid Garginox, the flesh giant that roams the vale.  I suspect you are not strong enough to defeat him.", sourceObjective = "Slay 16 Scourge and 8 Cultists within Browman Mill and the Noxious Glade. Return to Light's Hope Chapel if Tarenar or Gidwin is slain.", completion = "You've returned sooner than I expected.  Excellent.\n\nWe will continue our path into the north.  Next, you will be completing a similar task - this time, in Northdale.", sourceObjectiveStatus = "unverified-source-field" }
quests[27466] = { id = 27466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Call: Northdale", description = "Tyrosus has given us our next task: slaying more undead in Northdale.  Gidwin is excited to move forward, but I think we should show a little more caution.\n\nLet's meet up with Fiona.  She should be at the next tower by now... Eastwall Tower, I think it's called.  It's close by, to the northwest of Light's Hope.  We can rest there, and plan our attack on Northdale.", sourceObjective = "Speak with Fiona at Eastwall Tower in Eastern Plaguelands.", completion = "Hello, {name}!  Glad to see you've rejoined the caravan!\n\nTarenar and Gidwin arrived here before you.  Tarenar's just right there, and Gidwin's... well... he's in a little bit of a mood right now.  I think he's in the tower.", sourceObjectiveStatus = "unverified-source-field" }
quests[27467] = { id = 27467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Blades", description = "The Noxious Glade is a quagmire, both literally and figuratively.  There's enough Scourge up there to give us trouble for the rest of both of our lifetimes.\n\nThey can re-animate the weaker ones when they die, {name}.  They will never stop coming if we don't do something.\n\nTake these blades and drive them through the corpses of any Scourge troopers you find.  The blade is simple, but its enchantment will prevent the dead bones from being reanimated.  Forever.", sourceObjective = "Bury the Light-Touched Blades in the bodies of 10 Slain Scourge Troopers.", progress = "Are you still here?", completion = "Our duty for the day is done.\n\nIt is only a matter of time before we defeat the Scourge.  Today, we made progress.", sourceObjectiveStatus = "unverified-source-field" }
quests[27468] = { id = 27468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege Tank Rescue", description = "One by one, we're gonna have to pull our siege tanks outta the muck. Take these 'ere spare parts you've collected and give 'em to a siege tank commander who's standing on top of a gimped-up machine.\n\nThen defend the tank while engineers de-gimpify it.\n\nGo an' make me proud, {class}!", sourceObjective = "Speak with a Siege Tank Commander standing on top of a crippled Highbank Siege Tank. Defend the tank while engineers make repairs.", progress = "Rocks an' stumps an' hills an' mud... Bah.\n\nI hate nature.", completion = "Yep, one more tank limpin' back home for repairs.\n\nAll these trees an' stumps an' mud an' rock - you couldnae drive a golfball into this turf, much less a tank.\n\nWe're gonna need a new approach.", sourceObjectiveStatus = "unverified-source-field" }
quests[27469] = { id = 27469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends on The Other Side", description = "I come with news from Blackrock Spire. We have a new visitor. His name is Acride.\n\nHe seeks people of strength, people of intelligence, of dexterity. You ought to go to Blackrock Spire and speak with him.", sourceObjective = "Find Acride.", completion = "Hello, what is your business in a place like this?\n\nI'm sorry, who sent you? I'm afraid I've never heard of such an orc.", sourceObjectiveStatus = "unverified-source-field" }
quests[27470] = { id = 27470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Potential Ally", description = "It is no secret that we aren't fans of the orcs in Blackrock Mountain, but we do carefully watch their every move. Nothing happens in that Mountain without me knowing about it, {class}.\n\nRecently, a different sort of orc came into Blackrock. He resides just inside Blackrock Spire, and I know he's somehow planning to overthrow Nefarian and his whole army of orcs. Normally I wouldn't trust their kind, but we share a common goal for the time being. Find him, he's called Acride.", sourceObjective = "Find Acride.", completion = "Hello, what is your business in a place like this?\n\nSo Overseer Oilfist sent you? Listen carefully, we have much to discuss in little time.", sourceObjectiveStatus = "unverified-source-field" }
quests[27471] = { id = 27471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Anomaly", description = "There is an orc inside Blackrock Spire much unlike the others. He speaks with the intelligence and wisdom of one beyond his appeared years, and does not fight against our soldiers like the others do.\n\nYou must travel northwest to Blackrock Spire and find this orc, known only to us as Acride. Perhaps he is the key to stopping the orcish army. Perhaps we can stop Nefarian before it is too late...", sourceObjective = "Find Acride.", completion = "Hello, what is your business in a place like this?\n\nSo you come at the will of Miss Brightwing, do you? Very interesting indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27472] = { id = 27472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Godfrey", description = "You are unwavering in your loyalty to the Forsaken, {name}. Know that what you have done for us - for the Horde - will not go unnoticed. With Lord Godfrey and his men recovered, we will have a great advantage over the Gilneas Liberation Front and the rest of the Alliance dogs.\n\nNow stand by my side as Lord Godfrey is reborn as one of us. Together we will bring him and his men into the fold.", sourceObjective = "Stand by Lady Sylvanas Windrunner as she initiates Lord Godfrey and his men.", completion = "Today marks a new beginning for the Forsaken and the end of the Alliance in Lordaeron!", sourceObjectiveStatus = "unverified-source-field" }
quests[27474] = { id = 27474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Barrier", description = "While Godfrey and I make preparations for our assault upon Gilneas, I want you to lead our attack upon Ambermill, directly east of here.\n\nThe former Dalaran magi of Ambermill have erected a magical barrier that somehow cloaks them from vision. They currently reside within some type of pocket dimension, awaiting orders from the Alliance to begin their attack. We must prevent their assault by making a pre-emptive strike. Venture to Ambermill and find information that would grant us access to the mages.", sourceObjective = "Find the Ambermill Codex.", progress = "Have you found anything yet?", completion = "Clever mages. The codex is sealed by a magical ward.\n\nPity that they weren't clever enough to realize that former archmages of Dalaran are now Forsaken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27475] = { id = 27475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unyielding Servitors", description = "The magi of Ambermill have employed foul magic to keep us away. Elemental servitors created with immunities that we cannot breach protect their territory.\n\nVenture east to Ambermill and slay the unyielding elemental servitors that guard the town and recover their cores. Bring their cores back to me so that I may devise a method by which we are able to destroy them all!", sourceObjective = "Retrieve 6 Servitor Cores.", progress = "Have you recovered the servitor cores?", completion = "Well done, {name}. The praise the Banshee Queen lavishes upon you is apparently not unfounded.", sourceObjectiveStatus = "unverified-source-field" }
quests[27476] = { id = 27476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalar Dawnweaver", description = "Take the codex and travel north to the Sepulcher. Once there, find Dalar Dawnweaver. Dalar is a former archmage of the Kirin Tor. Surely he will be able to bring down the protective wards surrounding this codex and pry its secrets loose.\n\nHurry, {name}.", sourceObjective = "Deliver the Ambermill Codex to Dalar Dawnweaver at the Sepulcher in Silverpine Forest.", progress = "Yes? What is it?", completion = "The Dark Lady requires my expertise? Well of course! Give it here, boy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27477] = { id = 27477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corpulent One", description = "North of here and west of Northdale, you will find the corpulent maggot beast, Borelgore.\n\nI've lost entire regiments to that monster. His size knows no bounds! The more he eats the greater his girth becomes...\n\nWhile I would not suffer any emotional harm should the beast devour you, I would prefer that you were the victor.  Borelgore has been known to devour others who tried to hunt him.", sourceObjective = "Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him.", completion = "Keep this up and I may have to keep you here at Eastwall, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27478] = { id = 27478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relios the Relic Keeper", description = "The Dark Lady is correct in her assertion that I am able to unlock the codex. Unfortunately, I need a signet ring from a Dalaran archmage to do it. My own ring was taken when I died many years ago, but there still might be a way.\n\nWhile Dalaran has floated away, the outskirts of the city remain. Far to the east lie the ruins of Dalaran. It is there that you will find an archmage known as Relios. \"Take\" his signet ring and bring it back to me.\n\nYou may use the portal behind me to get to the crater.", sourceObjective = "Find a Dalaran Archmage's Signet Ring.", progress = "Did you recover a Dalaran Archmage's Signet Ring?", completion = "Perfect. I hope this wasn't too much trouble to come by, {name}. Relios was a pupil of mine back when I was a mortal man thereby making him a competent and formidable adversary. I suppose I could have warned you ahead of time.\n\nNow, let us see the ring.\n\n\n\nThere we are...", sourceObjectiveStatus = "unverified-source-field" }
quests[27479] = { id = 27479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Righteous Indignation", description = "The Mossflayers of Zul'Mashar spit in the face of the Light!  They cannibalize, they criminalize, they prioritize the forces of evil over good!  I advise that you remove their eyes, and give rise to the demise and the goodbyes of the unwise!\n\nYou will travel north, and you will rain down on them with righteous justice and indignation, {name}.  The fury that they have wrought in the eyes of the Light shall be channeled through you.", sourceObjective = "Obtain 30 Mossflayer Eyes from Mossflayer trolls in Zul'Mashar.", progress = "<Deacon Andaal is deep in prayer.>", completion = "Oh, hallelujah, and praise, praise be to the Light, my brother!", sourceObjectiveStatus = "unverified-source-field" }
quests[27480] = { id = 27480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ley Energies", description = "The arcane remnant pulses with strange energy. Perhaps you should search for more remnants. Surely Dalar would be interested in such a find.", sourceObjective = "Recover 8 Arcane Remnants.", progress = "What's that you've got there, {name}?", completion = "Smart boy! I can most definitely use these arcane remnants in my studies. Indeed, Dalaran was built upon a massive ley line. It's no wonder, then, that such things exist at the crater.", sourceObjectiveStatus = "unverified-source-field" }
quests[27481] = { id = 27481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Ziggurat", description = "It is time that I asked a favor of you, {name}.\n\nFar to the north of Eastwall Tower, hidden among the hills, is the Mossflayer capital city of Zul'Mashar.  It was here that I was born, and here that I died.\n\nThe traitor, Thresh'jin, sits atop Zul'Mashar's ziggurat.  It was my every right to be there, but he took the seat from me with treachery and deceit.  He is not strong.  He is weak.\n\nI will meet you in Zul'Mashar, and we will kill him.  Your strength and mine.  Together.", sourceObjective = "Obtain the Body of Warlord Thresh'jin.", progress = "I have waited long for this day.", completion = "My duty is not over yet.  In many ways, this was the easy step.", sourceObjectiveStatus = "unverified-source-field" }
quests[27482] = { id = 27482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Flames", description = "This is the last time you will see me, {name}.  I am leaving the caravan.\n\nIf you want to continue fighting by my side, hang on to Thresh'jin's body.  I can wait for a while longer.  When you are ready to say goodbye, throw the body into the bonfire atop Zul'Mashar's ziggurat.\n\nThank you for your companionship, {name}.  You were strong.", sourceObjective = "When you are ready to part with Vex'tul, throw Warlord Thresh'jin's body into the bonfire atop Zul'Mashar's ziggurat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27483] = { id = 27483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practical Vengeance", description = "Under ordinary circumstances I am not a vengeful man. In fact, I am somewhat of a pragmatist. You see, practicality is a paradoxical notion to vengeance. Most revenge ploys are highly impractical.\n\nBUT... in this case - since you're already going to the ruins of Dalaran - you might as well kill every Dalaran affiliated human that you see. The reasons that I want them dead range from hatred to anger to betrayal, but I assure you they are all legitimate gripes. Do this for me and I will pay you handsomely.", sourceObjective = "Kill any 12 Dalaran humans.", completion = "I thought for sure that with the death of a dozen of my most hated enemies I would feel a great burden lifted from my shoulders. Sadly, I do not feel a thing. Perhaps I am a psychopath.", sourceObjectiveStatus = "unverified-source-field" }
quests[27484] = { id = 27484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only One May Enter", description = "<Dalar flips through the codex.>\n\nHAHAH!\n\nOh... That's bad.\n\n<Dalar closes the codex and looks up at you.>\n\nWith this ring only ONE may enter the pocket dimension at Amber Mill. That person will then need to fight through an army of magi and kill the archmage that is generating the phase from the inside. Only then will the dimension fold, ejecting all of the magi.\n\nThe portal to entry is hidden at the back of a cave in Beren's Peril.\n\nThat's all I know. Take the ring back to Sylvanas.", sourceObjective = "Take the Dalaran Archmage's Signet Ring to Lady Sylvanas Windrunner at the Forsaken Front in Silverpine Forest.", progress = "What have you learned?", completion = "Only one may enter? I know just the person for this mission.\n\n<Sylvanas nods at you.>\n\nI will prepare our forces and have them at the ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[27485] = { id = 27485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warm Welcome", description = "I'm glad you're back! Saving the world or something, I'm sure.\n\nI was dispatched to establish relations with the red dragons in the area, but I'm finding this bunch somewhat less accommodating than the ones at Wyrmrest were. I have, however, been told that you are the type that solves problems.\n\nA problem solver as it were.\n\nCare to take a crack at earning a bit of trust with Lirastrasza at Vermillion Redoubt to the southwest? Anything that might soften her up a bit for me would be lovely.", sourceObjective = "Meet with Lirastrasza at Vermillion Redoubt.", progress = "I believe Lira wanted a word with you.", completion = "I'm glad Lira didn't scare you off. I won't say her concerns aren't warranted, but we have a common enemy. She is perhaps a bit overzealous.", sourceObjectiveStatus = "unverified-source-field" }
quests[27486] = { id = 27486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warm Welcome", description = "Good. You're back. Saving the world again I assume.\n\nI was dispatched to establish relations with the red dragons in the area, but I'm finding this bunch somewhat less accommodating than the ones at Wyrmrest were. I have, however, been told that you are the type that solves problems.\n\nA problem solver as it were.\n\nI need you to gain the trust of Lirastrasza at Vermillion Redoubt to the southwest. Our association with the Dragonmaw has complicated things, but I'm hoping you can ease relations.", sourceObjective = "Meet with Lirastrasza at Vermillion Redoubt.", progress = "I believe Lira wanted a word with you.", completion = "I'm glad Lira didn't scare you off. I won't say her concerns aren't warranted, but we have a common enemy. She is perhaps a bit overzealous.", sourceObjectiveStatus = "unverified-source-field" }
quests[27487] = { id = 27487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ix'lar the Underlord", description = "I know we're supposed to head to Northdale, but that can wait, right?  Besides, this lovely little goblin was just telling me about some Scourge that are even closer by.\n\nSo apparently there's this nerubian underlord named Ix'lar that has been trying to make a name for himself ever since the Lich King was slain.  He's set up a camp of undead to our north.\n\nSure, Tyrosus wants us to kill banshees in Northdale.  We'll get to that.  But let's kill this nerubian first, while we're close!", sourceObjective = "Kill Ix'lar the Underlord and 10 of his minions.", completion = "I couldn't stop him.  While you and Tarenar were out, Giddy ran north all alone!\n\nTarenar, you should have known better!  Gidwin gets so impatient sometimes, and you only egg him on.  If Giddy gets into any trouble, I'm blaming you for this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27488] = { id = 27488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impatience", description = "Damn that dwarf.  He's always getting me in trouble with Fiona.  Look at her!  She won't even TALK to me!\n\nI'm going to stay here and try to mend my friendship with our worgen friend.  Would you mind going out and making sure Gidwin is alright?  I'm sure he's fine; he knows how to take care of himself.  He headed north, and he can't have gone far.", sourceObjective = "Search for Gidwin Goldbraids in Northdale.", progress = "Northdale is home to a few ghosts and banshees.  Nothing ol' Giddy can't handle.", completion = "You didn't see him?  Where could he have gone then?\n\nHis... his prayer book?  Why would he leave that behind?\n\nOh...\n\nBy the Light, what have I done?", sourceObjectiveStatus = "unverified-source-field" }
quests[27489] = { id = 27489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nobody to Blame but Myself", description = "This is my fault.  I... I ignored his warnings, his complaints, everything.  I couldn't help myself - I saw those Scourge just beyond the tower, and I... I HAD to go kill them.\n\nArgus says that Gidwin was taken northwest, and that's our only lead, so that's where we'll head.\n\nNorthdale and the Argent Crusade be damned!  We're getting Gidwin back from those Scourge trash.", sourceObjective = "Hop in Fiona's Caravan and ride to Northpass Tower.", progress = "We have no time, {name}!  We must press on!", completion = "Time is wasting, {name}.  Every minute we waste gives the Scourge another chance to kill Gidwin.  If he isn't dead already.\n\nNot that I think he is.  Giddy may be a stick-in-the-mud, but when it comes down to it, he can swing the Light like a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[27490] = { id = 27490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Drop", description = "Mathias Shaw and the SI:7 are here to assist us with operations up top in the Twilight Citadel. I need you to escort them there.\n\nThe Wildhammer are being kind enough to give us a lift in. The agents have some things that they need to do down in the Twilight Gate area first, though.\n\nSpeak with Angus Stillmountain and get yourself a squad to drop off. You'll fly them in. A big blue X marks the spot.", sourceObjective = "Get a Wildhammer Hellions squad from Angus Stillmountain and then escort them to the drop off point in the Twilight Gate.", progress = "I need you to escort those SI:7 agents safely to their destination, {name}.", completion = "That must have been deadly.\n\nWhile I don't approve of their methods, no one can question the effectiveness of Master Mathias Shaw and his SI:7. Not to mention that you're here. Our victory is all but assured.", sourceObjectiveStatus = "unverified-source-field" }
quests[27491] = { id = 27491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kor'kron Drop", description = "Garona and a detachment of the Kor'kron are here to assist us with operations up top in the Twilight Citadel. I need you to escort them there.\n\nI've called upon a local tribe of trolls to give us a lift in with their wind riders. The assassins have some things that they need to do down in the Twilight Gate area first, though.\n\nSpeak with the troll chief, Jon-Jon Jellyneck and get yourself a detachment of Kor'kron to drop off. You'll fly them in. A big red X marks the spot.", sourceObjective = "Get a Crushblow Wind Rider squad from Jon-Jon Jellyneck and then escort them to the drop off point in the Twilight Gate.", progress = "I need you to get those Kor'kon assassins safely to their destination, {name}.", completion = "That must have been exciting.\n\nDespite any losses that the Kor'kron may have incurred along the way, no one will be able to doubt their effectiveness, nor that of Garona. And with you in the mix, it's only a matter of time before victory is ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[27492] = { id = 27492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogres & Ettins", description = "As with any offensive, you first need to soften them up. We've been having a heck of a time getting in there. But someone like you... well, let's just say I have no doubt in my mind that you can get into the Twilight Gate to the southwest and teach the Bloodeye Clan ogres and ettins a thing or two!", sourceObjective = "Slay 10 ogres or ettins at the Twilight Gate.", progress = "What's the matter? You Alliance boys don't have the stomach to get the job done?\n\n<Kurdran gives you a wink.>\n\nNeed me to fly over there and kill them for you?", completion = "That's the spirit, lad! Today's already shaping up to be a good one.", sourceObjectiveStatus = "unverified-source-field" }
quests[27493] = { id = 27493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogres & Ettins", description = "I want you to get in there past those boulders to the northwest at the Twilight Gate. Kill every Bloodeye Clan ogre and ettin in sight. Think you can handle that for me, {name}?", sourceObjective = "Slay 10 Bloodeye Clan ogres or ettins at the Twilight Gate.", progress = "There are more to be killed, {race}. You do have the stomach for that, yes?", completion = "And here I thought that today couldn't get any better.\n\nI enjoy being wrong, occasionally.", sourceObjectiveStatus = "unverified-source-field" }
quests[27494] = { id = 27494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Move the Mountain", description = "If the Twilight Gate is to fall, we need to get Skullcrusher the Mountain out of there!\n\nBefore they left, I saw to it that your SI:7 agents took some explosives hidden in a Twilight's Hammer crate. By now, they will have planted them on the steps leading up to the upper portion of the Citadel.\n\nI want you to set the explosives off and then signal us when that monster's out of the way.\n\nThat's when we'll attack and finish off the ogre compound!", sourceObjective = "Detonate the Hidden Explosives to lure Skullcrusher the Mountain away from the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27495] = { id = 27495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Move the Mountain", description = "If the Twilight Gate is to fall, we must get Skullcrusher the Mountain out of there!\n\nBefore they left, I saw to it that your Kor'kron assassins took some explosives hidden in a Twilight's Hammer crate. By now, they will have planted them on the steps leading up to the upper portion of the Citadel.\n\nI want you to set the explosives off and then signal us when that monster's out of the way.\n\nThat's when we'll attack and finish off the ogre compound!", sourceObjective = "Detonate the Hidden Explosives to lure Skullcrusher the Mountain away from the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27496] = { id = 27496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call in the Artillery", description = "I prefer a stand up honorable fight. These monsters deserve nothing better than to be destroyed by the weapons in our hands. However, this particular situation calls for the use of more powerful measures.\n\nTake this flare and mark each of the four buildings within the Twilight Gate to the southwest. Our cannons will handle the rest.", sourceObjective = "Use the Artillery Flare to target the Northern, Northeastern, Southwestern, and Southern buildings at the Twilight Gate.", completion = "Thanks to you, our cannoneers hit their marks. Tell me about the situation within the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27497] = { id = 27497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call in the Artillery", description = "A pity that we're no longer allowed to drop the Plague on our enemies. It would prove quite effective in this situation. Oh well, at least we have war machines to destroy their precious gates.\n\nI want you to take this flare. Use it to mark each of the four buildings within the Twilight Gate to the northwest. The war machines will handle the rest.", sourceObjective = "Use the Artillery Flare to target the Northern, Northeastern, Southwestern, and Southern buildings at the Twilight Gate.", completion = "I must say that I rather enjoyed the sight of their buildings being hit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27498] = { id = 27498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, it's time to signal your forces at Victor's Point to attack!", sourceObjective = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27499] = { id = 27499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, it's time to signal your forces at Crushblow to attack!", sourceObjective = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27500] = { id = 27500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Heads are Better than None", description = "Now while the attack upon the Twilight Gate is launched, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nYou're fairly certain that Cassius and Kurdran will want proof of their deaths.", sourceObjective = "Collect the four heads of Za'brox and Beeble'phod.", progress = "Is that blood dripping from your pack?", completion = "<The paladin frowns.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead. Regardless, thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27501] = { id = 27501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Heads are Better than None", description = "Now while the attack upon the Twilight Gate is launched, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nYou're fairly certain that Lady Cozwyn and Zaela will want proof of their deaths.", sourceObjective = "Collect the four heads of Za'brox and Beeble'phod.", progress = "Is that blood dripping from your pack? I hope that it's not yours.", completion = "<The noble lady grins wickedly.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead, though I do appreciate the extra effort. Thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27502] = { id = 27502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up to the Citadel", description = "Now that the attack is underway, it's time to deal with the Twilight Citadel. If you don't mind, I'd like for you to escort the SI:7 forces to Master Mathias Shaw.\n\nHe's hiding somewhere up top. The SI:7 squad commander can tell you where.\n\nThank you, {name}. We look forward to joining you in the assault upon the Citadel!", sourceObjective = "Speak with the SI:7 Squad Commander and then escort the SI:7 squad.", sourceObjectiveStatus = "unverified-source-field" }
quests[27503] = { id = 27503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up to the Citadel", description = "Now that the attack is underway, it's time to deal with the Twilight Citadel. If you don't mind, I'd like for you to escort the Kor'kron forces up to Garona.\n\nShe's hiding somewhere up top. The Kor'kron squad commander can tell you where.\n\nThank you, {name}. We look forward to joining you in the assault upon the Citadel!", sourceObjective = "Speak with the Kor'kron Squad Commander and then escort the Kor'kron squad.", sourceObjectiveStatus = "unverified-source-field" }
quests[27504] = { id = 27504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Even Dragons Bleed", description = "I won't be so impolite as to refuse your aid if you're offering it.\n\nWe're locked in constant battle with the twilight drakes and dragons to the south. Our strikes have not been entirely without success, but the dragons coming out of Grim Batol have been breathing some kind of corruption upon us that takes time to cleanse.\n\nVelastrasza and Baleflame are attending to our injured brothers. Go and see if you can be of help to them.", sourceObjective = "Speak to Velastrasza within the Vermillion Redoubt.", completion = "Calen has become very trusting. It is not often that strangers are permitted within the redoubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27505] = { id = 27505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Mending", description = "Our dragons are returning from battle covered in Twilight corrupted flame and pursued by Twilight drakes.\n\nMy menders can tend to our dragons' wounds, but they must be defended. Keep the drakes off of my menders. Lend your healing to our dragons as well if you are able.\n\nThank you for your help with this. Our battles for Grim Batol are never-ending. We need to get our strongest dragons back into the battle as soon as possible.", sourceObjective = "Safeguard 5 Vermillion Menders as they heal wounded dragons.", progress = "Keep the menders safe as they heal our wounded dragons!", completion = "We will take Grim Batol back from the Twilight's Hammer and their allies. It may take time, but this is one charge that we cannot forsake.", sourceObjectiveStatus = "unverified-source-field" }
quests[27506] = { id = 27506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life from Death", description = "{race}, I have a task for you.\n\nTake these ruby seeds and plant them at the corpses of any dragonkin that you come across. Twilight or Vermillion, whelping or dragon, it matters not. We need to see that their bodies are returned to the earth so that life can continue to flourish.\n\nIn death, there should always be new life. This may be our one consolation during times of war and great tragedy.", sourceObjective = "Plant Ruby Seeds at the corpses of 6 dragonkin within the Vermillion Redoubt.", progress = "Have you done as I asked?", completion = "In this, we deny Deathwing the destruction that he so passionately seeks. In this, life continues.", sourceObjectiveStatus = "unverified-source-field" }
quests[27507] = { id = 27507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Twilight", description = "Fragile Twilight invaders litter the redoubt. They're pouring in from somewhere to the west.\n\nThere can be no mercy offered to them within this hallowed place. Whatever violence grips your moral heart, release it upon them.", sourceObjective = "Kill 12 Twilight invaders within the Vermillion Redoubt.", completion = "You have a talent for killing I see. In times like these, that has its place.", sourceObjectiveStatus = "unverified-source-field" }
quests[27508] = { id = 27508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Far from the Nest", description = "Look... I know you have no reason to be fond of me, just as I'm not terribly fond of you, but I need any help I can get.\n\nOur eggs are being stolen by these Twilight invaders. I have no doubt that they want to take them back to Grim Batol to experiment on and pervert. I will NOT let that happen.\n\nIf you truly do want to help us, stop them! Recover the eggs. Bring them back to me.", sourceObjective = "Recover 6 Vermillion Eggs.", progress = "Twilight dragons were born of these disgusting experiments of theirs. The Twilight's Hammer have gone too far. Deathwing has gone too far.", completion = "I don't know if you did this for me or the young inside these eggs, but it doesn't really matter, either way it's clear that you want to be an ally of our flight. I appreciate that.\n\nI cannot forgive the attacks by your allies against my brood, but for now, it seems you have chosen the right side.", sourceObjectiveStatus = "unverified-source-field" }
quests[27509] = { id = 27509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breach in the Defenses", description = "Every inch of air and every hill surrounding the redoubt is constantly under the watchful eye of Lira's drakes. They must have found a way into the shrine from beneath.\n\nTake this Flashgrowth mote. It should prove more than sufficient to close any hole, tunnel, or portal they might have used to get inside our defenses.\n\nFind the breach in our defenses. Close it.", sourceObjective = "Find the source of the Twilight's Hammer in the Vermillion Redoubt and destroy it.", completion = "Well done. Thank you, {race}.\n\nI will not be so foolish as to let such an oversight happen again.", sourceObjectiveStatus = "unverified-source-field" }
quests[27510] = { id = 27510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wolf in Bear's Clothing", description = "These worgen take us for fools! One would think that only an idiot would mistake one of their druids in bear form as a real bear. Unfortunately, there are many idiots here at the Forsaken Front. We've already lost a few battalions to organized worgen bear attacks. Yes, it's even more idiotic than it sounds.\n\nDirectly east of here, heading towards Hillsbrad, you will find worgen druids roaming the woods, masquerading as bears. Kill them and make our southern supply line safe again.", sourceObjective = "Kill 10 Inconspicuous Bears.", completion = "I only hope that we don't end up getting beat down by inconspicuous birds, cats and trees next... or seals. Could you imagine it?", sourceObjectiveStatus = "unverified-source-field" }
quests[27511] = { id = 27511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thrill of Discovery", description = "What a find! And somehow it's all remained untouched by plunderers...\n\nListen, {name}. I need to document this site before we disturb anything. While I do, why don't you have a look around - you know, explore a bit. You've earned it.\n\nKeep your eyes open for anything unusual.\n\nOh! And please... don't break anything, ok?", sourceObjective = "Explore the Chamber of the Stars.", progress = "Find anything interesting, {name}?", completion = "Your exploration of the Chamber of the Stars has yielded more questions than answers...", sourceObjectiveStatus = "unverified-source-field" }
quests[27512] = { id = 27512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transdimensional Warfare: Chapter I", description = "<Sylvanas hands you the signet ring.>\n\nTake the ring and make your way to Beren's Peril, southeast of here, located in a cave in the hills. Once there, search the cave for the portal to the pocket dimension that conceals the Ambermill magi.\n\nI will communicate with you through your thoughts, {name}. Once you have reached the portal I will give you your marching orders.", sourceObjective = "Find the Ambermill Dimensional Portal.", progress = "<The portal hums.>", completion = "<The Banshee Queen's voice invades your thoughts.>\n\nYes, this is it. Now run the ring along the runes of the portal and you should become attuned for transdimensional travel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27513] = { id = 27513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transdimensional Warfare: Chapter II", description = "<The Banshee Queen's words float in your head.>\n\nYou are now ready to use the portal. Be warned, {name}, once you step through you will appear in another dimension at Ambermill. There will be a hundred, perhaps a thousand, magi waiting to kill you.\n\nYou must persevere and kill all in your path.", sourceObjective = "Kill 20 Ambermill mages.", completion = "<The Banshee Queen's voice invades your thoughts.>\n\nExcellent work, {name}. Now to eject them into our waiting hands!", sourceObjectiveStatus = "unverified-source-field" }
quests[27514] = { id = 27514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bird Down! Bird Down!", description = "While you were fighting along the coast, I spotted a gryphon tumble out of the clouds almost due west of here.\n\nIt wasn't one of ours.\n\nLikely it belonged to one of the Wildhammer. I know that Kurdran wanted to establish contact with the lost Wildhammer clans as one of his primary objectives after taking the beach. \n\nI can't spare any more of my men to scout it out, but I can spare you. Find that downed Wildhammer!", sourceObjective = "Locate Thordun Hammerblow, a downed Wildhammer gryphon-rider, at the Twilight Shores in Twilight Highlands.", completion = "Aw dang crap it all. You're just an Alliance {class}. I was hoping for a rescue.", sourceObjectiveStatus = "unverified-source-field" }
quests[27515] = { id = 27515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roots'll Do 'Er", description = "Look here, mate. She's on her last legs! If me bird dies, I'm as good as worthless.\n\nSo make yerself useful. Here on the peninsula you can dig up thorny stankroots. Oh the smell will knock you on yer patoot but steeped in water it'll boil up into a right powerful cure-all.\n\nGather some while I defend me bird. An' hurry! You Alliance wanks don't have a reputation for timely intervention, right?", sourceObjective = "Gather 8 Thorny Stankroots from the Twilight Shores.", progress = "Didja get me roots, {class}? Well?", completion = "Oh, that's the stuff all right! Hope ya didn't eat any. Gives you the cramps something awful but it does wonders for birds.", sourceObjectiveStatus = "unverified-source-field" }
quests[27516] = { id = 27516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wings Over Highbank", description = "Aye, look! I think she's perkin' up already.\n\nOkay <Mr./Miss> Alliance fancy-pants {class}. Is that your base I see on the shore? \"Highbank\" you say. Can me and my bird hunker down there until she's better?\n\nHop on! We'll fly together back to Highbank!", sourceObjective = "Speak with Thordun Hammerblow and fly together back to Highbank.", progress = "What's the news from the peninsula, {name}?", completion = "Well done, {name}! Aiding that downed gryphon-rider has given us our first contact with the old Wildhammer clans. We'll be able to find out who's still left, and in what numbers.\n\nOur campaign is looking up!", sourceObjectiveStatus = "unverified-source-field" }
quests[27517] = { id = 27517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be Prepared", description = "Every adventurer worth their salt knows never to step foot in a cave, dungeon, crypt or tomb without an ample supply of rope... right?\n\nYou can never have too much of this stuff!\n\nYou resolve to scrounging every scrap of it you can find from the skeletons here.", sourceObjective = "Collect 6 Rope Pieces.", progress = "What have you found, {name}?", completion = "Ahh, rope! Thanks, kid.\n\nSomething tells me I'm going to need this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27518] = { id = 27518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transdimensional Warfare: Chapter III", description = "<Sylvanas speaks directly through you.>\n\nYou must find the being responsible for keeping this dimensional pocket active. Likely that fool, Ataeric... Search the compound for him. Should you find him, do what you must to stop him from channeling his magic. He is undoubtedly protected by a powerful arcane shield, and will send minions of arcane energy after you.  Defeat the minions while they are near him to unleash their energies.  No mage can handle that much power!", sourceObjective = "Overload Archmage Ataeric with arcane power to bring down the Transdimensional Shield.", completion = "Had I not witnessed what you did with my own eyes I would not have believed it, {name}. Now, with the Ambermill magi on our side, there is but one thing left to do before we retake Gilneas and send those Alliance dogs running for Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27519] = { id = 27519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under the Choking Sands", description = "No... it cannot be.\n\nOrsis is all but buried beneath the desert sands.\n\nThe enemy will pay for this.\n\nBut first we must aid my people.  Quick, {name}.  We do not have much time before the last of my brethren are buried alive!", sourceObjective = "Rescue 8 Orsis Survivors.", completion = "I thank you, {name}.  Orsis was punished for not joining the forces of Deathwing.\n\nPrince Nadun has offered my people refuge in his city.  I must go there and tend the survivors.", sourceObjectiveStatus = "unverified-source-field" }
quests[27520] = { id = 27520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minions of Al'Akir", description = "Al'Akir has sent his minions to do Deathwing's bidding.\n\nThe message is clear.  We join them or they destroy us.\n\nI do not know much about you, {race}.  But I do know this.  If you prove yourself to be an enemy of Al'Akir's, your aid will not go unnoticed.\n\nWhat do you say, {class}?", sourceObjective = "Slay 6 Scions of Al'Akir.", progress = "You're back!", completion = "You continue to prove to be a valuable ally, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27521] = { id = 27521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wretched Hive of Scum and Villainy", description = "{race}... please, I ask your help.\n\nSomething's happened to my people.  Our commander, Ranger Lord Hawkspear, came upon an item of magical energy, and my friends, my family... they succumbed to its seductive power.\n\nThey're corrupted, {race}.  All of them.\n\nMy Ellaria wouldn't want to live like that, nor would any of my brothers.  Please, put them out of their misery.  Quel'lithien Lodge is not far; it's just up the hill, to the northwest.", sourceObjective = "Kill 9 Wretched at Quel'lithien Lodge in Eastern Plaguelands.", completion = "Do not feel sorry for me.  Those were my friends that you saw at Quel'lithien Lodge, but they were already as good as dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[27522] = { id = 27522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beat it Out of Them", description = "We paladins are normally taught to exercise judgment and control when dealing with foes, but this is an emergency, and I never paid too much attention to my trainers anyhow.\n\nI'm going to head into the Plaguewood and find out what I can about Giddy.  You deal with the Scourge just to our northeast, on the other side of this tower.  The undead don't fear death, but if you beat them enough, their tongues might slip, and we may get some clues to Gidwin's location.", sourceObjective = "Beat down at least 6 Scourge Siege Engineers to discover details about Gidwin's location and his captor.", completion = "It sounds like you were successful.  Hopefully this is enough information to find Gidwin.", sourceObjectiveStatus = "unverified-source-field" }
quests[27523] = { id = 27523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwing, Oh How I Hate Thee...", description = "I have seen many things in my day, {race}.  The peaks of Mt. Hyjal... the oddities of Outland... a wall of Scourge soldiers, proceeding into war.  But I have never seen a bat as big, or as shockingly white, as Duskwing.\n\nHow he taunts me from his roost!\n\nThis albino demon bat circles to the southwest of here, due north of Blackwood Lake.  Track him down and destroy him.  If he flies too high for you to reach, use my flare to get his attention.", sourceObjective = "Obtain a Patch of Duskwing's Fur.", progress = "I hope you've done away with that creature.", completion = "Excellent work.  I can now continue my work without the distractions of that great white beast.\n\nI shall fashion this fur into something you can use.", sourceObjectiveStatus = "unverified-source-field" }
quests[27524] = { id = 27524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Fury", description = "Tarenar wasn't joking when he said that he didn't care about judgment and caution.  He nearly took off that high elf's head as he ran into the Plaguewood, looking for Gidwin.  You should go after him.\n\nThe Plaguewood is a big place, {name}.  Good luck.  I hope to see you <boys/three> come out of the woods in one piece.", sourceObjective = "Find Tarenar Sunstrike within the Plaguewood in Eastern Plaguelands.", completion = "I haven't found anything but brainless undead, and plenty of them.  I was just about to kill my way into Stratholme when you arrived.\n\nDid you have any more success?", sourceObjectiveStatus = "unverified-source-field" }
quests[27525] = { id = 27525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardians of Stratholme", description = "Baroness Anastar holds him?  Here in the Plaguewood?\n\nThe Plaguewood is a big place... but we will find him.  We WILL find Gidwin.\n\nImmediately to our east and our west are a pair of necropoli that flank the entrance to Stratholme.  Inside them, you will find a pair of death knights - Rivendare's lieutenants.  I doubt either would have any use for a paladin hostage, but perhaps they will have some information on his location.", sourceObjective = "Kill Omasum Blighthoof and Karthis Darkrune.", completion = "We've got to keep moving!  We're getting so very close!", sourceObjectiveStatus = "unverified-source-field" }
quests[27526] = { id = 27526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin's Fate Revealed", description = "Quickly - find an entrance to the slaughterhouse to our south.  I will meet you on the inside.\n\nBe ready for a fight!", sourceObjective = "Search for Gidwin Goldbraids within the slaughterhouse in central Plaguewood.", completion = "You have no idea how happy I am to see you two!  You're a sight for sore eyes... sore eyes that have been starin' through a banshee for far too long now.\n\nI'm sorry for causing so much trouble.  Will you take me back to the caravan?", sourceObjectiveStatus = "unverified-source-field" }
quests[27527] = { id = 27527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey's End", description = "I've had just about enough of the funk of this place.  Undead stink is bad enough, and then you add mushrooms to the mix?  I hate mushrooms!\n\nI'm going to head back to Light's Hope Chapel, {name}... and I'm taking Tarenar and Fiona with me.  I think we've all earned a well-deserved break.\n\nLet me give you this.  It's my hearthstone - you can use it to travel instantly back to Light's Hope.  I won't need it - I'm going to be riding in the caravan.\n\nIn the FRONT SEAT.", sourceObjective = "Speak with Fiona at Light's Hope Chapel in Eastern Plaguelands.\n\nProvided item:", completion = "You've been more help than anyone expected of you, {name}.  The doors of my caravan are always open to you.\n\nThe boys and I have even put together a little something special for you.  Here, take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[27528] = { id = 27528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourged Mass", description = "You can't just kill the Scourge.  They will come back.  You must destroy the vile matter that makes up their being... and even then, they may come back as spectres.\n\nFew undead use up as much mass as the lumbering abominations.  Kill them, then burn their bodies.  You will find them all over the Plaguewood.\n\nNever let your rage dissipate, {race}.  Remember: these abominations are sewn together from the bodies of good people.  Their crime is that they exist.", sourceObjective = "Kill 8 Overstuffed Golems, then use the Crusader's Torch on their corpses.", completion = "A blessed fire cleanses even the most corrupt of flesh.\n\nThey stood no chance in the face of the Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[27529] = { id = 27529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defenders of Darrowshire", description = "The battle of Darrowshire was one of the many tragedies that we humans suffered at the hands of the Scourge.  Its effects are still felt even today.\n\nMany of the town's valiant defenders now roam again as the ghastly servants of the Scourge.  We will end their misery.\n\nHunt cannibal ghouls here within the Plaguewood.  Many of these fiends were once the good folk of Darrowshire, and destroying their forms now will set their souls free.", sourceObjective = "Free 8 Darrowshire Spirits from the bodies of Cannibal Ghouls, then speak with them.", completion = "It is good to hear you found the tortured souls of my brethren and freed them.  I find my strength renewed, knowing at least some of the defenders of Darrowshire no longer wallow in the vile subservience of the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[27530] = { id = 27530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corpsebeasts", description = "To the south, gutless cultists are focused on a grim task: re-animating enormous hunks of flesh, to create giants known as corpsebeasts.  Luckily for us, these giants are still lifeless and weak.\n\nTake this charm - using it will place a font of holy energy on the ground.  If you can manage to place three of them near one of the corpsebeasts that the cultists are reanimating, the holy energy should overload it, destroying its body forever.", sourceObjective = "Destroy the hulks of three Corpsebeasts by placing three or more Argent Lightwells next to them. You cannot place Argent Lightwells while in combat, and you may not place them within ten yards of one another.", completion = "You are a true Champion of the Light, {name}.  I wish you luck in your future endeavors, wherever they might take you.\n\nIf you need anything in the future, you can always find me here - knee-deep in the corpses of the slain.", sourceObjectiveStatus = "unverified-source-field" }
quests[27531] = { id = 27531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Counter-Plague Research", description = "I once worked for the so-called \"Banshee-Queen\", Sylvanas, as an apothecary.  I used to admire her, but something's changed within her.  She's not herself anymore.\n\nI broke my vows with the Forsaken and joined the Crusade.  Now, I use my knowledge of alchemy to seek a counter-plague agent.  And the Plaguewood is the perfect place to do so.\n\nI need to resupply a few reagents, any of which can be found within the Plaguewood.  I'll pay you if you can find any of these items.", sourceObjective = "Obtain 20 Rotberries, 5 Disembodied Arms, and 1 pile of Flesh Giant Foot Scrapings.", progress = "You got the stuff?", completion = "I love the smell of fresh foot scrapings, don't you?\n\nIf we're going to find a cure to the plague, we need to get creative with our ingredients.  Now, if you don't mind, I'm going to get back to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[27532] = { id = 27532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plaguewood Tower", description = "With the recent, unfortunate developments involving Gidwin, it might not be wise for a man my age to take the dangerous trip through the Plaguewood.  This is fine - I can visit the Plaguewood Tower on my next trip around the loop.\n\nI do, however, have a delivery that I need to get to Judkins.  You are younger than I, and stronger in combat.  Will you take this delivery to him?", sourceObjective = "Bring Highbeacon's Parcel to Argent Apothecary Judkins at Plaguewood Tower in Eastern Plaguelands.", progress = "Highbeacon's Parcel... is Argus safe?  Did something happen?", completion = "Whew.  Every time Argus comes plodding through that Plaguewood, I fear it to be his last.  It's good to see that he's wise enough to send a youngblood like you in his stead.", sourceObjectiveStatus = "unverified-source-field" }
quests[27533] = { id = 27533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fate Worse Than Butchery", description = "The people of Terrordale, they were sick, then they turned bad.  Definitely not good times.\n\nThe pigs, though... they also got sick!  What did pigs do to deserve to get sick?  Hah hah hah!  Nothing!\n\nPeople I can forget about, but the bad pigs still make me sad.  If you kill them, though... I might get happy.", sourceObjective = "Kill 9 Plagued Swine.", completion = "I see them!  Can you?  The little pig spirits, on their way to the great sty in the sky...", sourceObjectiveStatus = "unverified-source-field" }
quests[27534] = { id = 27534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augustus' Receipt Book", description = "I'm ready for business!  What do you want?\n\nOh wait... I can't open up shop without my receipt book.  How am I to keep track of things without my receipt book?\n\nI must have left it in town somewhere.  I had a room in the inn... the book must be there.\n\nBring me my book.  Please, bring it to me!  Bring me my book and you'll see!  I'll set up shop and you'll see that my prices are INSANE!", sourceObjective = "Get Augustus' Receipt Book from the inn in Terrordale.", progress = "Do you have my receipt book?  I can't wait to get back to business!", completion = "There it is!  And oh my!  I forgot how full it was!\n\nThis is a glorious day, {name}!  Stupendous!  Insanely good, I say!", sourceObjectiveStatus = "unverified-source-field" }
quests[27535] = { id = 27535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Little Touched", description = "I like to check in on Augustus in Terrordale every once in a while, just to make sure he's alright.  Some of us undead cope with the plague better than others, I suppose.\n\nTerrordale is west of here.  Would you mind checking in on him for me?", sourceObjective = "Speak with Augustus the Touched in Terrordale.", completion = "You've come to the right place, mister!  No place better than Terrordale, yes siree, that's right!  The jewel of Lordaeron!", sourceObjectiveStatus = "unverified-source-field" }
quests[27536] = { id = 27536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mostly Harmless", description = "Here's another favor you can do for me, pal.\n\nWe had a whole shipment of Landmines come in from Booty Bay just the other day. But someone stole the whole lot of 'em in the night!\n\nWhoever it was must be sloppy, because they dropped them all over the swamp to the east. No goblin I know would be that careless.\n\nI need you to go gather those landmines up for me. I'm sure they're perfectly safe and disarmed. Every single one. Yup.", sourceObjective = "Collect 8 Disarmed Land Mines from the Sorrowmurk to the east of Bogpaddle.", progress = "Hey, you get those things I asked you about?", completion = "What did I tell you, eh? Perfectly safe!\n\nI'll see about getting some of these over to to your friends, {name}. At a discount.", sourceObjectiveStatus = "unverified-source-field" }
quests[27537] = { id = 27537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Any Portal in a Storm", description = "Our friends in the Earthen Ring have been trying to open portals back to Stormwind, with no luck. But Thordun here tells me he might just have the key.\n\nThe crazed water elementals in the nearby Verrall River Delta have been sent into a frenzy. Thordun tells me we can channel their energy into a portal.\n\nI don't understand all this elemental-claptrap, but I understand one thing: killin' elementals and takin' their whirlpool cores. Deliver them to Talaa in the courtyard!", sourceObjective = "Slay Muddied Water Elementals to collect 5 Whirlpool Cores.", progress = "Hello, {class}. Kurdran tells me you've got a solution to getting this portal opened?", completion = "My word, {name}. These elemental energies are so powerful, so chaotic - no wonder the Twilight's Hammer has chosen to build their stronghold here!\n\nI should be able to channel these energies into something more benign and productive though. Let's give it a try...", sourceObjectiveStatus = "unverified-source-field" }
quests[27538] = { id = 27538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Poultice", description = "Are you goin' by way of the Verrall river delta? I've got a tip that'll help your men here... and my bird!\n\nWhen water elementals carve their way through rock, they create a peculiar kind of muck. It dries hard as stone but carries with it the rejuvenating power of water. You make a cast out of that muck and broken bones knit together like iron.\n\nBring some of that muck to Talaa, your shaman downstairs. She'll know what to do with it!", sourceObjective = "Collect 10 piles of Verrall River Muck.", progress = "What is this I keep hearing about the muck of the Verrall River?", completion = "Oh... mud. You brought me mud?\n\nWow - this stuff oozes with power! I see what Thordun was saying, now. I'll distribute this to all of the healers. Our wounded will be on their feet in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[27539] = { id = 27539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Add 'em to the Pile", description = "I've been collecting the skulls of the skeletons I defeat.  I've amassed a small pile of them.\n\nIf you come across any skulls, you are welcome to add them to my pile.  The huge pile of skulls seems to keep the waves of undead at bay and... well... it also just makes me happy to look at it.", sourceObjective = "Obtain 16 Stinking Skulls from Cursed Mages and Scourge Soldiers in the Plaguewood.", progress = "You seem to have your hands full.  Are those skulls I see?", completion = "May my pile never stop growing.", sourceObjectiveStatus = "unverified-source-field" }
quests[27541] = { id = 27541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons From the Past", description = "This unfortunate explorer has clearly suffered a bit of bad luck in the recent past.\n\nPrudence dictates that you perform the unenviable task of searching the corpse for clues that might shed light on your surroundings...", sourceObjective = "Acquire the Broken Goggles.", progress = "Any news, {name}?", completion = "Odd...\n\nIt looks as if someone used gemstones as lenses.\n\nI should be able to fix them without too much trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[27542] = { id = 27542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Battlefront", sourceObjective = "The hour of victory approaches, {name}. Godfrey has devised a plan to decimate our enemies. I am sending you into the field with him and his men to bring the rebel insurgents to their knees and seal the fate of the Alliance filth encroaching upon our lands.\n\nOur final march begins when you are ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[27544] = { id = 27544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarion Tenacity", description = "Those druids never give up, I swear.  I'd given up on the Plaguelands years ago, but the Cenarion Circle folks keep telling me that the land is not beyond hope.\n\nThe most recent visitor was a night elf, on her way to the Fungal Vale, to the north.  She told me that these lands will make a full recovery, if we try hard enough.  I'm not sure I believe her.\n\nDo you buy this drivel?  Maybe you and her should talk.  She should still be up there.", sourceObjective = "Speak with Rayne near the entrance to the Fungal Vale.", completion = "I suppose I had better work on my stealth, if you were able to find me.\n\nAre you interested in helping me heal the Plaguelands?", sourceObjectiveStatus = "unverified-source-field" }
quests[27545] = { id = 27545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way is Open", description = "My fellow Shaman and I will stay here to keep the portal open.\n\nYou should go upstairs and notify Kurdran that the work here is done. It'll please him to hear some good news for once.", sourceObjective = "Speak with Kurdran Wildhammer at Highbank in Twilight Highlands.", completion = "Ho! I knew you were a {class} I could count on, {name}. Use that portal anytime you need to get from Stormwind back to the Highlands.\n\nNow then, time to get to business. We need to locate and unite the lost Wildhammer clans scattered around the Highlands. Talking with Thordun here is a good start!", sourceObjectiveStatus = "unverified-source-field" }
quests[27546] = { id = 27546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Captain Anton", description = "No doubt you've felt the earthquakes.  You may even have seen elementals attacking the lands or towns. We have sent many of our brightest minds to Nagrand to commune with the elements.\n\nBut there is still much work to be done here.  Stormwind Guards are being overwhelmed with citizens worried about their loved ones.\n\nPlease, {class}, speak with Captain Anton in Stormwind Keep and see how you might assist him.", sourceObjective = "Speak with Captain Anton in Stormwind Keep.No doubt you've felt the earthquakes. You may even have seen elementals attacking the lands or towns. We have sent many of our brightest minds to Nagrand to commune with the elements.\n\nBut there is still much work to be done here. Stormwind Guards are being overwhelmed with citizens worried about their loved ones.\n\nPlease, {class}, speak with Captain Anton in Stormwind Keep and see how you might assist him.", sourceObjectiveStatus = "unverified-source-field" }
quests[27547] = { id = 27547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of No Consequence", description = "Our forces in Pyrewood were recently taken by way of sneak attack. The 7th Legion managed to infiltrate the town with their scouts, ultimately decimating our troops.\n\nThe Dark Lady has tasked us with a rescue mission. We are to find survivors and get them out of Pyrewood safely. If any soldiers live they are likely worthless, but we do as the Dark Lady commands.\n\nLet's get this nonsense over with, {name}. Pyrewood is directly southwest of the Forsaken Front.", sourceObjective = "Rescue 8 Cowering Troopers.", progress = "The sooner we rescue survivors the sooner we can burn down the whole of Pyrewood.", completion = "What happened here today is between us. Say a word to anyone and you will find yourself in a corpse pit next to these poor fools.", sourceObjectiveStatus = "unverified-source-field" }
quests[27548] = { id = 27548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons in Fear", description = "Our enemies are becoming smarter - adapting to our tactics. Recently an attack was made upon Pyrewood Village, southwest of here. Our troops occupying the town were decimated, of course, but what made the attack especially interesting was the racial composition of the attacking force. No humans were used.\n\n<Walden laughs.>\n\nRightfully, they fear being reanimated as Forsaken.\n\nLet us teach the non-humans a lesson in fear. Together we will show them what happens to corpses that we cannot use.", sourceObjective = "Kill 12 7th Legion Scouts.", progress = "Pyrewood Village must be reduced to ashes and our enemies slain!", completion = "I suspect we'll see fewer humans at the Battlefront. The risk for these cowards is too great.", sourceObjectiveStatus = "unverified-source-field" }
quests[27549] = { id = 27549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By the Light of the Stars", description = "Look at this, {name}.\n\n<Harrison holds up the dead scout's goggles.>\n\nI tightened the clamp in the middle and crimped the wires on the edges. They may not be the most comfortable, but they should hold together.\n\nIf I've translated your tablets correctly, there's something hidden here - a final piece to our puzzle.\n\nI hope your spectacles hold the key.\n\nLet me know what you find!", sourceObjective = "Collect 7 Suspended Starlight.", progress = "So?\n\nFind anything interesting?", completion = "Well, kid, it looks like you've done it again.\n\n<Harrison points to an image on the tablets.>\n\nThis starlight is exactly what we were missing.\n\nNow we can get to work!", sourceObjectiveStatus = "unverified-source-field" }
quests[27550] = { id = 27550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyrewood's Fall", description = "The attacks against our front are a distraction. With our attention turned towards the worgen onslaught, the Alliance has managed to take Pyrewood Village from our occupying forces.\n\n<Godfrey hands you a bundle of torches.>\n\nIt must be purged.\n\nWith these torches we will burn Pyrewood Village to the ground, leaving only ashes for the enemy to hide behind.\n\nLet us not waste another minute. Pyrewood Village is located southwest of the Forsaken Front. Lead us there, {name}.", sourceObjective = "Use the Bundle of Torches to torch the Pyrewood Town Hall, Pyrewood Inn and Pyrewood Chapel.", progress = "I feel no remorse.", completion = "The part of me that was Gilnean died at Tempest's Reach. Only vengeance remains, {name}. To that end, we have work to do. Spare me your pointless queries.", sourceObjectiveStatus = "unverified-source-field" }
quests[27551] = { id = 27551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Baroness' Missive", description = "The note is from Baroness Anastari, and it describes a ritual that is about to happen in the Plaguewood's central slaughterhouse - just south of where Tarenar is at.  This could be where they're holding Gidwin!\n\nTarenar will want to know about this... and quickly, before it's too late!", sourceObjective = "Bring the Baroness' Missive to Tarenar.", progress = "What?  Did you find something?", completion = "This is it!  If this missive is to be believed, then he's literally right over this hill!\n\nWhat are we waiting for, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27555] = { id = 27555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiona's Lucky Charm", sourceObjective = "Fiona has left some of her charms inside the caravan.\n\nAs a trader, she seems to be pretty good with money.  Maybe carrying one of her charms will help out with your finances.", sourceObjectiveStatus = "unverified-source-field" }
quests[27556] = { id = 27556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin's Weapon Oil", sourceObjective = "Gidwin has left several bottles of weapon oil inside the caravan.\n\nHe seems to be quite a fierce combatant up close.  Perhaps his weapon oil will help you out as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27557] = { id = 27557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarenar's Talisman", sourceObjective = "Tarenar has laid a few holy talismans inside the caravan.  They appear to be unused.\n\nThey appear to be magical in nature.  If Tarenar isn't using them, what's the harm in borrowing one for a while?", sourceObjectiveStatus = "unverified-source-field" }
quests[27558] = { id = 27558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamela's Doll", sourceObjective = "You see a small doll sitting in the back corner of the caravan.\n\nTarenar tells you that it must belong to Gidwin, and Gidwin says that it's probably Tarenar's.", sourceObjectiveStatus = "unverified-source-field" }
quests[27559] = { id = 27559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vex'tul's Armbands", sourceObjective = "Vex'tul has left some of his wrappings within the caravan.  Surprisingly, he was courteous enough to keep them folded and separate from everyone else's belongings.\n\nVex'tul values strength over everything else.  Leaning in close, you can sense some of his residual strength emanating from within these armbands.", sourceObjectiveStatus = "unverified-source-field" }
quests[27560] = { id = 27560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argus' Journal", sourceObjective = "You see a trail-worn journal inside the caravan.  Judging by the Argent Crusade emblem on its spine, it must belong to Argus.\n\nWritten within the journal are several accounts of Argus' experiences during his tenure in the Crusade.  It should prove to be an interesting read while on the road.", sourceObjectiveStatus = "unverified-source-field" }
quests[27561] = { id = 27561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rimblat's Stone", sourceObjective = "You notice a small heap of stones within the caravan.\n\nThey do not appear out-of-the-ordinary, yet one of them attracts your attention.  You sense a warmth coming from within it.", sourceObjectiveStatus = "unverified-source-field" }
